1	import {
2	  pageAbout,
3	  mainBackground,
4	  sceneTransitionVeil,
5	} from "../core/setup.js";
6	import { ABOUT_AFTER_INTRO_AUTOPLAY_ENABLED } from "../pages/about/theatre/AboutTheatreConfig.js";
7	import { EnvSetup } from "../app/EnvSetup.js";
8	import { ScrollLock } from "../utils/ScrollLock.js";
9	import { HudPanel } from "../ui/HudPanel.js";
10	import { Panel } from "../ui/Panel.js";
11	import { IntroOverlay } from "../ui/IntroOverlay.js";
12	import { TextReveal } from "../animation/TextReveal.js";
13	import { BlockReveal } from "../animation/BlockReveal.js";
14	import { DOM_CONFIG } from "../config/dom.config.js";
15	import { SCENE_TRANSITION_VEIL_SEQUENCE } from "../config/transition.config.js";
16	import type { GsapGlobal } from "../types/gsap.types.js";
17	import type {
18	  AboutPageConfig,
19	  AboutSceneSectionKey,
20	} from "../types/about.types.js";
21	import type { ContactPageConfig } from "../types/contact.types.js";
22	import type {
23	  MainPageConfig,
24	  MainSceneSectionKey,
25	} from "../types/main.types.js";
26	import type { AppPageConfig } from "../types/runtime.types.js";
27	import type { IntroConfig } from "../types/core.types.js";
28	import type { IntroControllerDependencies } from "../types/intro.types.js";
29	
30	const MAIN_FLOW = DOM_CONFIG.keys.mainFlow;
31	const INTRO_ACTION_CONTENT_SELECTOR =
32	  MAIN_FLOW?.introActionContent ?? ".no-main-intro-action__content";
33	const INTRO_ACTION_TO_HERO_DURATION = 1.18;
34	const INTRO_ACTION_TO_HERO_OFFSET_Y = -32;
35	const ABOUT_HERO_INTRO_TEXT_SELECTOR =
36	  ".no-sub-about-hero-intro .mask-target";
37	const ABOUT_HERO_INTRO_TOP_SELECTOR =
38	  ".no-sub-about-hero-intro__top.is-block-reveal";
39	const ABOUT_HERO_INTRO_BOTTOM_BLOCK_SELECTOR =
40	  ".no-sub-about-hero-intro__desc.is-block-reveal, .no-sub-about-hero-intro__info.is-block-reveal";
41	const ABOUT_HERO_INTRO_REVEAL_STAGGER_MS = 140;
42	const MAIN_DEBUG_WHO_TEXT_SELECTOR = ".no-main-who .mask-target";
43	const MAIN_DEBUG_WHY_TEXT_SELECTOR = ".no-main-why .mask-target";
44	const MAIN_DEBUG_WHY_BODY_SELECTOR = ".no-main-why__body";
45	const MAIN_DEBUG_WHY_VISUAL_SELECTOR = ".no-main-why__visual";
46	const MAIN_DEBUG_WHY_CARD_SELECTOR = ".no-main-why__card";
47	const MAIN_DEBUG_WORKS_DETAIL_HEAD_SELECTOR = ".no-main-portfolio__head";
48	const MAIN_DEBUG_WORKS_DETAIL_TEXT_SELECTOR = ".no-main-portfolio__head .mask-target";
49	const MAIN_DEBUG_CONTACT_HEAD_SELECTOR = ".no-main-contact__head";
50	const MAIN_DEBUG_CONTACT_TEXT_SELECTOR = ".no-main-contact .mask-target";
51	
52	export class IntroController {
53	  private readonly _dependencies: IntroControllerDependencies;
54	
55	  constructor(dependencies: IntroControllerDependencies) {
56	    this._dependencies = dependencies;
57	  }
58	
59	  hasIntro(pageConfig: AppPageConfig, gsap: GsapGlobal | null): boolean {
60	    return !!this._resolveIntroOverlay(pageConfig)?.tl && !!gsap;
61	  }
62	
63	  async runMainIntro(
64	    pageConfig: MainPageConfig,
65	    objectSetupPromise: Promise<void>,
66	    gsap: GsapGlobal,
67	  ): Promise<void> {
68	    const introConfig = this._resolveIntroOverlay(pageConfig);
69	    if (!introConfig) return;
70	    const isDebugMode = EnvSetup.hasQueryFlag("debug", "1");
71	
72	    await this._dependencies.introFlowRuntime.run({
73	      introConfig,
74	      gsap,
75	      loadPromise: this._dependencies.runAfterLoad(
76	        pageConfig,
77	        objectSetupPromise,
78	        { deferScrollSync: true },
79	      ),
80	      root: this._dependencies.getRoot(),
81	      disableScrollLock: isDebugMode,
82	      showDebugDomState: isDebugMode,
83	      keepIntroActionVisible: isDebugMode,
84	      onAfterIntroAutoplay: isDebugMode
85	        ? undefined
86	        : async () => {
87	            const engine = this._dependencies.getEngine();
88	            if (!engine) return;
89	            await this._dependencies.startPageTheatreAfterIntro(engine);
90	          },
91	      onIntroDomRevealComplete: () => {
92	        this._dependencies.onMainIntroDomRevealComplete();
93	        if (isDebugMode) {
94	          this._dependencies.dom.setHeroHandoffVisible(true);
95	          TextReveal.setVisibleOn(MAIN_DEBUG_WHO_TEXT_SELECTOR);
96	          TextReveal.setVisibleOn(MAIN_DEBUG_WHY_TEXT_SELECTOR);
97	          document
98	            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_BODY_SELECTOR)
99	            ?.style.setProperty("opacity", "1");
100	          document
101	            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_BODY_SELECTOR)
102	            ?.style.setProperty("visibility", "visible");
103	          document
104	            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_BODY_SELECTOR)
105	            ?.style.setProperty("transform", "translate3d(-50%, -50%, 0)");
106	          document
107	            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_VISUAL_SELECTOR)
108	            ?.style.setProperty("opacity", "1");
109	          document
110	            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_VISUAL_SELECTOR)
111	            ?.style.setProperty("visibility", "visible");
112	          document
113	            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_VISUAL_SELECTOR)
114	            ?.style.setProperty("transform", "translate3d(-50%, -50%, 0)");
115	          document
116	            .querySelectorAll<HTMLElement>(MAIN_DEBUG_WHY_CARD_SELECTOR)
117	            .forEach((card) => {
118	              card.style.setProperty("--card-opacity", "1");
119	            });
120	          document
121	            .querySelector<HTMLElement>(MAIN_DEBUG_WORKS_DETAIL_HEAD_SELECTOR)
122	            ?.setAttribute("data-active", "true");
123	          TextReveal.setVisibleOn(MAIN_DEBUG_WORKS_DETAIL_TEXT_SELECTOR);
124	          document
125	            .querySelector<HTMLElement>(MAIN_DEBUG_CONTACT_HEAD_SELECTOR)
126	            ?.setAttribute("data-active", "true");
127	          TextReveal.setVisibleOn(MAIN_DEBUG_CONTACT_TEXT_SELECTOR);
128	        }
129	      },
130	          onIntroActionAutoplay: isDebugMode
131	        ? undefined
132	        : async () => {
133	            const engine = this._dependencies.getEngine();
134	            if (!engine) return;
135	            const hudPanel = HudPanel.getInstance();
136	            hudPanel.setVisibleOn();
137	            hudPanel.setIntroActionFlightEnabled(false);
138	            this._dependencies.syncMainIntroBackground(pageConfig, "introAction", 1);
139	            await this._dependencies.startMainIntroActionPhaseOne(engine);
140	            const wasSkipped =
141	              await this._dependencies.introFlowRuntime.playIntroActionCountdown(
142	                this._dependencies.getGsap(),
143	              );
144	            if (wasSkipped) {
145	              hudPanel.setIntroActionFlightEnabled(false);
146	              hudPanel.syncFlightProgress("hero", 0, "hero");
147	              return;
148	            }
149	            hudPanel.startIntroActionFlight();
150	            await Promise.all([
151	              this._dependencies.startMainIntroActionPhaseTwo(engine),
152	              this._dependencies.introFlowRuntime.playIntroActionStorySequence(
153	                this._dependencies.getGsap(),
154	              ),
155	            ]);
156	          },
157	      onIntroActionTransition: isDebugMode
158	        ? undefined
159	        : async () => {
160	            await this._transitionMainIntroToHero(pageConfig);
161	          },
162	      onPreviewStart: isDebugMode
163	        ? undefined
164	        : this._dependencies.startPagePreviewIfNeeded,
165	    });
166	  }
167	
168	  async runAboutIntro(
169	    pageConfig: AboutPageConfig,
170	    objectSetupPromise: Promise<void>,
171	    gsap: GsapGlobal,
172	  ): Promise<void> {
173	    const introConfig = this._resolveIntroOverlay(pageConfig);
174	    if (!introConfig) return;
175	
176	    this._dependencies.dom.setAboutScenePlanesVisible(pageConfig, false);
177	    this._dependencies.dom.setAboutUiPhase("intro");
178	
179	    const introRunner = new IntroOverlay(introConfig);
180	    let releaseAboutScrollLock: (() => void) | null = null;
181	    try {
182	      await introRunner.run({
183	        gsap,
184	        loadPromise: this._dependencies.runAfterLoad(
185	          pageConfig,
186	          objectSetupPromise,
187	          { deferScrollSync: true },
188	        ),
189	      });
190	
191	      const engine = this._dependencies.getEngine();
192	      if (!engine) return;
193	
194	      releaseAboutScrollLock = ScrollLock.lock({ pauseLenis: true });
195	      this._prepareAboutHeroIntroDomReveal();
196	      await this._dependencies.dom.revealAboutScenePlanes(pageConfig, gsap);
197	      await this._dependencies.startPageTheatreIntro(engine);
198	      Panel.getInstance().setVisibleOn();
199	      await this._playAboutHeroIntroDomReveal();
200	      await this._dependencies.syncAboutSceneState(pageConfig, "heroIntro", 1);
201	      if (ABOUT_AFTER_INTRO_AUTOPLAY_ENABLED) {
202	        await this._dependencies.startPageTheatreAfterIntro(engine);
203	        await this._dependencies.syncAboutSceneState(pageConfig, "heroSlogan", 1);
204	      }
205	      this._finishAboutIntro(pageConfig, releaseAboutScrollLock);
206	      releaseAboutScrollLock = null;
207	      await this._dependencies.startPagePreviewIfNeeded();
208	    } finally {
209	      releaseAboutScrollLock?.();
210	      introRunner.dispose();
211	    }
212	  }
213	
214	  async runContactIntro(
215	    pageConfig: ContactPageConfig,
216	    objectSetupPromise: Promise<void>,
217	  ): Promise<void> {
218	    await this._dependencies.runAfterLoad(
219	      pageConfig,
220	      objectSetupPromise,
221	      { deferScrollSync: true },
222	    );
223	
224	    const engine = this._dependencies.getEngine();
225	    if (!engine) {
226	      this._dependencies.syncContactDomState(null);
227	      return;
228	    }
229	
230	    await this._dependencies.runContactIntroSequence(engine);
231	    Panel.getInstance().setVisibleOff();
232	    HudPanel.getInstance().setVisibleOff();
233	    ScrollLock.unlock();
234	  }
235	
236	  private async _transitionMainIntroToHero(
237	    pageConfig: MainPageConfig,
238	  ): Promise<void> {
239	    this._dependencies.onMainIntroTransitionStateChange(true);
240	    try {
241	      this._dependencies.introHandoffRuntime.setHeroTextVisible(false);
242	      this._dependencies.dom.setHeroHandoffVisible(false);
243	      await this._dependencies.introHandoffRuntime.transitionToHero({
244	        gsap: this._dependencies.getGsap(),
245	        transitionRuntime: this._dependencies.sceneTransitionRuntime,
246	        veil: this._dependencies.resolveTransitionVeil(sceneTransitionVeil),
247	        steps: [
248	          SCENE_TRANSITION_VEIL_SEQUENCE.cover,
249	          SCENE_TRANSITION_VEIL_SEQUENCE.hold,
250	          SCENE_TRANSITION_VEIL_SEQUENCE.reveal,
251	        ],
252	        inactiveProgress: SCENE_TRANSITION_VEIL_SEQUENCE.inactiveProgress,
253	        actionContentSelector: INTRO_ACTION_CONTENT_SELECTOR,
254	        actionContentOffsetY: INTRO_ACTION_TO_HERO_OFFSET_Y,
255	        actionContentDuration: INTRO_ACTION_TO_HERO_DURATION,
256	        onCoverComplete: async () => {
257	          this._dependencies
258	            .getEngine()
259	            ?.getBackgroundManager()
260	            ?.startTransition(mainBackground);
261	          await this._dependencies.syncMainSceneState(pageConfig, "hero", 0);
262	        },
263	      });
264	      this._dependencies.dom.setHeroHandoffVisible(true);
265	      await this._dependencies.introHandoffRuntime.playHeroTextRise();
266	      this._finishMainIntro(pageConfig);
267	    } finally {
268	      this._dependencies.onMainIntroTransitionStateChange(false);
269	    }
270	  }
271	
272	  private _finishMainIntro(pageConfig: MainPageConfig): void {
273	    HudPanel.getInstance().setVisibleOn();
274	    Panel.getInstance().setVisibleOff();
275	    window.scrollTo({ top: 0, behavior: "auto" });
276	    this._dependencies.introFlowRuntime.releaseScrollLock();
277	    this._dependencies.startMainScrollSyncAfterIntro(pageConfig);
278	  }
279	
280	  private _finishAboutIntro(
281	    pageConfig: AboutPageConfig,
282	    releaseScrollLock: (() => void) | null,
283	  ): void {
284	    HudPanel.getInstance().setVisibleOff();
285	    this._dependencies.startAboutScrollSyncAfterIntro(pageConfig);
286	    releaseScrollLock?.();
287	    window.requestAnimationFrame(() => {
288	      this._dependencies.dom.scrollToAboutSceneProgress(pageConfig, "heroIntro", 0);
289	    });
290	  }
291	
292	  private _resolveIntroOverlay(pageConfig: AppPageConfig): IntroConfig | null {
293	    return pageConfig.introOverlay ?? pageConfig.intro ?? null;
294	  }
295	
296	  private _prepareAboutHeroIntroDomReveal(): void {
297	    TextReveal.setVisibleOff(ABOUT_HERO_INTRO_TEXT_SELECTOR);
298	    BlockReveal.hide(ABOUT_HERO_INTRO_TOP_SELECTOR);
299	    BlockReveal.hide(ABOUT_HERO_INTRO_BOTTOM_BLOCK_SELECTOR);
300	  }
301	
302	  private async _playAboutHeroIntroDomReveal(): Promise<void> {
303	    BlockReveal.reveal(ABOUT_HERO_INTRO_TOP_SELECTOR);
304	    const textItems = Array.from(
305	      document.querySelectorAll<HTMLElement>(ABOUT_HERO_INTRO_TEXT_SELECTOR),
306	    );
307	    if (textItems.length > 0) {
308	      await new Promise<void>((resolve) => {
309	        let completed = 0;
310	        textItems.forEach((item, index) => {
311	          window.setTimeout(() => {
312	            TextReveal.riseUp(item);
313	            completed += 1;
314	            if (completed === textItems.length) {
315	              resolve();
316	            }
317	          }, index * ABOUT_HERO_INTRO_REVEAL_STAGGER_MS);
318	        });
319	      });
320	    }
321	    BlockReveal.reveal(ABOUT_HERO_INTRO_BOTTOM_BLOCK_SELECTOR);
322	    await new Promise<void>((resolve) => {
323	      window.setTimeout(resolve, ABOUT_HERO_INTRO_REVEAL_STAGGER_MS * 2);
324	    });
325	  }
326	}
