import type { IntroHeroTransitionOptions } from "../types/runtime.types.js";
import { TextReveal } from "../animation/TextReveal.js";

const HERO_REVEAL_SELECTOR = ".no-main-hero__reveal";
const HERO_TEXT_RISE_STAGGER_MS = 140;

export class IntroHandoffRuntime {
  async transitionToHero(options: IntroHeroTransitionOptions): Promise<void> {
    const {
      gsap,
      transitionRuntime,
      veil,
      steps,
      inactiveProgress,
      actionContentSelector,
      actionContentOffsetY,
      actionContentDuration,
      onCoverComplete,
      onTransitionComplete,
    } = options;

    await transitionRuntime.play(
      {
        veil,
        steps,
        onStepComplete: async (stepIndex) => {
          if (stepIndex !== 0) return;
          await onCoverComplete?.();
          await this._fadeActionContent(
            gsap,
            actionContentSelector,
            actionContentOffsetY,
            actionContentDuration,
          );
        },
        initialState: {
          active: true,
          progress: steps[0]?.from ?? 0,
        },
        finalState: {
          active: false,
          progress: inactiveProgress,
        },
      },
      gsap,
    );
    onTransitionComplete?.();
  }

  setHeroTextVisible(visible: boolean): void {
    const textItems = this._getHeroTextItems();
    if (textItems.length === 0) return;
    if (visible) {
      TextReveal.setVisibleOn(textItems);
      return;
    }
    TextReveal.setVisibleOff(textItems);
  }

  async playHeroTextRise(): Promise<void> {
    const textItems = this._getHeroTextItems();
    if (textItems.length === 0) return;
    TextReveal.setVisibleOff(textItems);
    await new Promise<void>((resolve) => {
      let completedCount = 0;
      textItems.forEach((item, index) => {
        window.setTimeout(() => {
          TextReveal.riseUp(item);
          completedCount += 1;
          if (completedCount !== textItems.length) return;
          resolve();
        }, index * HERO_TEXT_RISE_STAGGER_MS);
      });
    });
  }

  private async _fadeActionContent(
    gsap: IntroHeroTransitionOptions["gsap"],
    actionContentSelector: string,
    actionContentOffsetY: number,
    actionContentDuration: number,
  ): Promise<void> {
    const actionContent = document.querySelector<HTMLElement>(actionContentSelector);
    if (!actionContent) return;

    if (!gsap) {
      actionContent.style.opacity = "0";
      actionContent.style.transform = `translateY(${actionContentOffsetY}px)`;
      actionContent.style.filter = "blur(16px)";
      return;
    }

    await new Promise<void>((resolve) => {
      gsap.to(actionContent, {
        autoAlpha: 0,
        y: actionContentOffsetY,
        filter: "blur(16px)",
        duration: actionContentDuration,
        ease: "power2.inOut",
        onComplete: () => resolve(),
      });
    });
  }

  private _getHeroTextItems(): HTMLElement[] {
    return Array.from(
      document.querySelectorAll<HTMLElement>(HERO_REVEAL_SELECTOR),
    );
  }
}

