import type { GsapGlobal } from "../types/gsap.types.js";
import { Helpers } from "../utils/Helpers.js";
import type {
  SceneTransitionPlayOptions,
  SceneTransitionStep,
} from "../types/runtime.types.js";
import type {
  TransitionEaseKey,
  TransitionVeilRuntimePort,
} from "../types/object-runtime.types.js";

const DEFAULT_INACTIVE_PROGRESS = 1;

export class SceneTransitionRuntime {
  syncVeil(veil: TransitionVeilRuntimePort | null, progress: number): void {
    if (!veil) return;
    veil.setRuntimeState({
      active: true,
      progress: Helpers.clamp01(progress),
    });
  }

  resetVeil(
    veil: TransitionVeilRuntimePort | null,
    inactiveProgress = DEFAULT_INACTIVE_PROGRESS,
  ): void {
    if (!veil) return;
    veil.setRuntimeState({
      active: false,
      progress: Helpers.clamp01(inactiveProgress),
    });
  }

  async play(
    options: SceneTransitionPlayOptions,
    gsap: GsapGlobal | null,
  ): Promise<void> {
    const { veil, steps, onStepComplete, initialState, finalState } = options;
    if (!veil || steps.length === 0) {
      if (onStepComplete) await onStepComplete(0);
      return;
    }

    veil.setRuntimeState({
      active: true,
      progress: Helpers.clamp01(initialState?.progress ?? steps[0]?.from ?? 0),
      ...initialState,
    });

    if (!gsap) {
      for (let index = 0; index < steps.length; index += 1) {
        veil.setRuntimeState({
          active: true,
          progress: Helpers.clamp01(steps[index].to),
        });
        if (onStepComplete) await onStepComplete(index);
      }
      veil.setRuntimeState({
        active: false,
        progress: Helpers.clamp01(
          finalState?.progress ?? steps[steps.length - 1]?.to ?? 1,
        ),
        ...finalState,
      });
      return;
    }

    for (let index = 0; index < steps.length; index += 1) {
      await this._playStep(gsap, veil, steps[index]);
      if (onStepComplete) await onStepComplete(index);
    }

    veil.setRuntimeState({
      active: false,
      progress: Helpers.clamp01(
        finalState?.progress ?? steps[steps.length - 1]?.to ?? 1,
      ),
      ...finalState,
    });
  }

  private async _playStep(
    gsap: GsapGlobal,
    veil: TransitionVeilRuntimePort,
    step: SceneTransitionStep,
  ): Promise<void> {
    const state = { progress: Helpers.clamp01(step.from) };
    veil.setRuntimeState({
      active: true,
      progress: state.progress,
    });

    await new Promise<void>((resolve) => {
      gsap.to(state, {
        progress: Helpers.clamp01(step.to),
        duration: Math.max(0, step.duration),
        ease: this._resolveEase(step.ease),
        onUpdate: () => {
          veil.setRuntimeState({
            active: true,
            progress: state.progress,
          });
        },
        onComplete: () => resolve(),
      });
    });
  }

  private _resolveEase(ease: TransitionEaseKey | undefined): string {
    if (ease === "easeInOutCubic") return "power2.inOut";
    return "none";
  }
}

export const CLOUD_TEXTURES = {
  perlinTextureUrl: "/resource/images/texture/clouds/uniform9_img.png",
  noiseTextureUrl: "/resource/images/texture/clouds/uniform10_img.png",
} as const;

export const BACKGROUND_APP_DOM = {
  rendererFallbackBackground:
    "linear-gradient(180deg, #050813 0%, #0b1834 52%, #17284a 100%)",
  portfolioHeadSelector:
    '.no-main-portfolio[data-scene="worksDetail"] .no-main-portfolio__head',
  portfolioGallerySelector:
    '.no-main-portfolio-gallery[data-scene="worksFinal"]',
  worksOverlaySelector: ".no-overlay",
} as const;

export const WORKS_DETAIL_HEAD_TRANSITION = {
  revealStart: 0.12,
  revealStagger: 0.12,
  hideStart: 0.92,
  hideStagger: 0.08,
  hideSettleDuration: 1.05,
} as const;

export const CONTACT_HEAD_TRANSITION = {
  revealStart: 0.18,
  revealStagger: 0.14,
  hideStart: 0.78,
  hideStagger: 0.1,
  hideSettleDuration: 1.12,
} as const;

export const BACKGROUND_CLOUD_PLANE_OPTIONS = {
  width: 5,
  height: 5,
  segments: 1,
  curveDepth: 0,
  curvePower: 1,
} as const;

export const TRANSITION_VEIL_PLANE = {
  width: 840,
  height: 620,
  segments: 1,
  curveDepth: 0,
  curvePower: 1,
  distance: 16,
} as const;

export const TRANSITION_VEIL_SHADER = {
  textures: CLOUD_TEXTURES,
  opacity: 0.96,
  noiseStrength: 1,
  revealSoftness: 0.32,
  size: { x: 3.0, y: 2.2 },
} as const;

export const CLOUD_SHADER_BASE = {
  textures: CLOUD_TEXTURES,
  ratio: 2,
  size: { x: 1, y: 1 },
  chapter: 0,
  transition: 0,
} as const;

export const SCENE_TRANSITION_VEIL_SEQUENCE = {
  cover: {
    from: 1,
    to: 0,
    duration: 1.26,
    ease: "easeInOutCubic",
  },
  hold: {
    from: 0,
    to: 0,
    duration: 0.88,
    ease: "easeInOutCubic",
  },
  reveal: {
    from: 0,
    to: 1,
    duration: 1.92,
    ease: "easeInOutCubic",
  },
  inactiveProgress: 1,
} as const;

