import { PCFSoftShadowMap } from "three";
import type { PageThreeConfig } from "../../../types/core.types.js";
import { getDefaultThreeConfig } from "../../../config/base.config.js";
import { EnvSetup } from "../../../app/EnvSetup.js";
import {
  mainBackground,
  cloud,
  cloud2,
  cloud3,
  cloud4,
  cloud5,
  cloud6,
  earth,
  ground,
  planet,
  rocket,
  jetEngine,
  sceneLights,
  terrian,
  sceneTransitionVeil,
  windowObj,
} from "../../../core/setup.js";
import {
  createMainInitialSceneState,
  createMainPostProcessingOptions,
} from "../theatre/MainSceneState.js";
import { MainSceneRig } from "../theatre/MainSceneRig.js";
import type {
  MainPageConfig,
  MainSceneSectionKey,
  MainTheatreSheetId,
} from "../../../types/main.types.js";
import { BlockReveal } from "../../../animation/BlockReveal.js";
import { TextReveal } from "../../../animation/TextReveal.js";
import { Helpers } from "../../../utils/Helpers.js";
import { runIntroDomTimeline } from "../../../runtime/IntroLoadingRuntime.js";
import { INIT_DOM_CLASSES } from "../../../config/dom.config.js";
import {
  MAIN_BACKGROUND_CLIENT_LOOK,
  MAIN_BACKGROUND_CONTACT_LOOK,
  MAIN_BACKGROUND_HERO_LOOK,
  MAIN_BACKGROUND_INTRO_LOOK,
  MAIN_BACKGROUND_INTRO_ACTION_LOOK,
  MAIN_BACKGROUND_SERVICES_LOOK,
  MAIN_BACKGROUND_STORY_LOOK,
  MAIN_BACKGROUND_WHO_LOOK,
  MAIN_BACKGROUND_WHY_LOOK,
  MAIN_BACKGROUND_WORKS_DETAIL_LOOK,
  MAIN_BACKGROUND_WORKS_FINAL_LOOK,
  MAIN_BACKGROUND_WORKS_LOOK,
} from "../../../config/background.config.js";
import {
  BACKGROUND_APP_DOM as APP_MANAGER_DOM,
  CONTACT_HEAD_TRANSITION,
  WORKS_DETAIL_HEAD_TRANSITION,
} from "../../../config/transition.config.js";
import type {
  PageSceneRuntimePolicy,
  SceneBackgroundPolicy,
  SceneProgressOptionsMap,
  SceneSelectorMap,
} from "../../../types/runtime.types.js";
import type {
  BackgroundTransitionRule,
  BackgroundVariantKey,
  SceneProgressTransitionWindow,
} from "../../../types/object-runtime.types.js";

const MAIN_THEATRE_QUERY_KEY = "theatre";
const MAIN_THEATRE_QUERY_ENABLED = "1";
const WHO_TEXT_SELECTOR = ".no-main-who .mask-target";
const WHO_REVEAL_START = 0.12;
const WHO_REVEAL_END = 0.92;
const WHO_REVEAL_STAGGER_SECONDS = 0.12;
const CLIENT_ITEM_SELECTOR = ".no-main-clients__item";
const CLIENT_REVEAL_START = 0.08;
const CLIENT_REVEAL_END = 0.96;
const CLIENT_REVEAL_STAGGER_SECONDS = 0.045;
const CONTACT_SECTION_SELECTOR = ".no-main-contact";
const CONTACT_HEAD_SELECTOR = ".no-main-contact__head";
const CONTACT_ACTIONS_SELECTOR = ".no-main-contact__actions";
const CONTACT_ACTION_ITEM_SELECTOR =
  ".no-main-contact__actions > .no-corner-btn-wrap";
const WORKS_DETAIL_HEAD_SELECTOR = APP_MANAGER_DOM.portfolioHeadSelector;
const MAIN_IS_AUTHOR_MODE = EnvSetup.hasQueryFlag(
  MAIN_THEATRE_QUERY_KEY,
  MAIN_THEATRE_QUERY_ENABLED,
);
const MAIN_SCENE_RIG = new MainSceneRig();
const mainInitialSceneState = createMainInitialSceneState();
const initialState = MAIN_SCENE_RIG.compose(
  mainInitialSceneState,
) as NonNullable<MainPageConfig["initialState"]>;
const initialCameraPosition = {
  x: initialState.camera?.position?.x ?? 0,
  y: initialState.camera?.position?.y ?? 0,
  z: initialState.camera?.position?.z ?? 0,
};
const initialCameraTargetPosition = {
  x: initialState.cameraTarget?.position?.x ?? 0,
  y: initialState.cameraTarget?.position?.y ?? 0,
  z: initialState.cameraTarget?.position?.z ?? 0,
};
const defaultThree = getDefaultThreeConfig();
const initialCameraFov = initialState.camera?.fov ?? defaultThree.camera.fov;
const initialPostProcessing = createMainPostProcessingOptions(
  mainInitialSceneState.postProcessing,
);
const mainSceneDomState = {
  isWhoTextVisible: false,
  whoTextTimers: [] as number[],
  isWorksDetailHeadVisible: false,
  worksDetailHeadTimers: [] as number[],
  isClientItemsVisible: false,
  clientItemTimers: [] as number[],
  isContactHeadVisible: false,
  contactHeadTimers: [] as number[],
  isContactActionsVisible: false,
  contactActionTimers: [] as number[],
};

function clearTimers(timerIds: number[]): number[] {
  timerIds.forEach((timerId) => {
    window.clearTimeout(timerId);
  });
  return [];
}

function syncWhoScene(progress: number): void {
  const textItems = Array.from(
    document.querySelectorAll<HTMLElement>(WHO_TEXT_SELECTOR),
  );
  if (textItems.length === 0) return;

  const shouldShow = progress >= WHO_REVEAL_START && progress < WHO_REVEAL_END;
  if (mainSceneDomState.isWhoTextVisible === shouldShow) return;
  mainSceneDomState.isWhoTextVisible = shouldShow;
  mainSceneDomState.whoTextTimers = clearTimers(
    mainSceneDomState.whoTextTimers,
  );

  const items = shouldShow ? textItems : textItems.slice().reverse();
  items.forEach((item, index) => {
    const timerId = window.setTimeout(
      () => {
        if (shouldShow) {
          TextReveal.setVisibleOn(item);
          return;
        }
        TextReveal.setVisibleOff(item);
      },
      index * WHO_REVEAL_STAGGER_SECONDS * 1000,
    );
    mainSceneDomState.whoTextTimers.push(timerId);
  });
}

function disposeWhoScene(): void {
  mainSceneDomState.isWhoTextVisible = false;
  mainSceneDomState.whoTextTimers = clearTimers(
    mainSceneDomState.whoTextTimers,
  );
  const textItems = Array.from(
    document.querySelectorAll<HTMLElement>(WHO_TEXT_SELECTOR),
  );
  textItems.forEach((item) => TextReveal.setVisibleOff(item));
}



function syncWorksDetailHead(progress: number): void {
  const head = document.querySelector<HTMLElement>(WORKS_DETAIL_HEAD_SELECTOR);
  if (!head) return;
  const textItems = Array.from(
    head.querySelectorAll<HTMLElement>(".mask-target"),
  );
  const shouldShow =
    progress >= WORKS_DETAIL_HEAD_TRANSITION.revealStart &&
    progress < WORKS_DETAIL_HEAD_TRANSITION.hideStart;

  if (mainSceneDomState.isWorksDetailHeadVisible === shouldShow) return;
  mainSceneDomState.isWorksDetailHeadVisible = shouldShow;
  mainSceneDomState.worksDetailHeadTimers = clearTimers(
    mainSceneDomState.worksDetailHeadTimers,
  );

  if (shouldShow) {
    head.dataset.active = "true";
    TextReveal.setVisibleOff(textItems);
    textItems.forEach((item, index) => {
      const timerId = window.setTimeout(
        () => {
          TextReveal.setVisibleOn(item);
        },
        index * WORKS_DETAIL_HEAD_TRANSITION.revealStagger * 1000,
      );
      mainSceneDomState.worksDetailHeadTimers.push(timerId);
    });
    return;
  }

  textItems
    .slice()
    .reverse()
    .forEach((item, index) => {
      const timerId = window.setTimeout(
        () => {
          TextReveal.setVisibleOff(item);
        },
        index * WORKS_DETAIL_HEAD_TRANSITION.hideStagger * 1000,
      );
      mainSceneDomState.worksDetailHeadTimers.push(timerId);
    });
  const hideTimerId = window.setTimeout(
    () => {
      head.dataset.active = "false";
    },
    (Math.max(textItems.length - 1, 0) *
      WORKS_DETAIL_HEAD_TRANSITION.hideStagger +
      WORKS_DETAIL_HEAD_TRANSITION.hideSettleDuration) *
      1000,
  );
  mainSceneDomState.worksDetailHeadTimers.push(hideTimerId);
}

function disposeWorksDetailHead(): void {
  mainSceneDomState.isWorksDetailHeadVisible = false;
  mainSceneDomState.worksDetailHeadTimers = clearTimers(
    mainSceneDomState.worksDetailHeadTimers,
  );
  const head = document.querySelector<HTMLElement>(WORKS_DETAIL_HEAD_SELECTOR);
  if (!head) return;
  head.dataset.active = "false";
  const textItems = Array.from(
    head.querySelectorAll<HTMLElement>(".mask-target"),
  );
  textItems.forEach((item) => TextReveal.setVisibleOff(item));
}

function syncClientItems(progress: number): void {
  const items = Array.from(
    document.querySelectorAll<HTMLElement>(CLIENT_ITEM_SELECTOR),
  );
  if (items.length === 0) return;

  const shouldShow =
    progress >= CLIENT_REVEAL_START && progress < CLIENT_REVEAL_END;
  if (mainSceneDomState.isClientItemsVisible === shouldShow) return;
  mainSceneDomState.isClientItemsVisible = shouldShow;
  mainSceneDomState.clientItemTimers = clearTimers(
    mainSceneDomState.clientItemTimers,
  );

  const queue = shouldShow ? items : items.slice().reverse();
  queue.forEach((item, index) => {
    const timerId = window.setTimeout(
      () => {
        item.classList.add(INIT_DOM_CLASSES.blockBase);
        item.classList.remove(INIT_DOM_CLASSES.boxHidden);
        item.classList.remove("is-block-reveal-down");
        if (shouldShow) {
          BlockReveal.reveal(item);
          return;
        }
        item.classList.remove(INIT_DOM_CLASSES.blockUp);
        item.classList.add("is-block-reveal-down");
      },
      index * CLIENT_REVEAL_STAGGER_SECONDS * 1000,
    );
    mainSceneDomState.clientItemTimers.push(timerId);
  });
}

function disposeClientItems(): void {
  mainSceneDomState.isClientItemsVisible = false;
  mainSceneDomState.clientItemTimers = clearTimers(
    mainSceneDomState.clientItemTimers,
  );
  const items = Array.from(
    document.querySelectorAll<HTMLElement>(CLIENT_ITEM_SELECTOR),
  );
  items.forEach((item) => {
    item.classList.add(INIT_DOM_CLASSES.blockBase);
    item.classList.remove(INIT_DOM_CLASSES.blockUp, "is-block-reveal-down");
    item.classList.add(INIT_DOM_CLASSES.boxHidden);
  });
}

function syncContactHead(progress: number): void {
  const section = document.querySelector<HTMLElement>(CONTACT_SECTION_SELECTOR);
  const head = document.querySelector<HTMLElement>(CONTACT_HEAD_SELECTOR);
  const actions = document.querySelector<HTMLElement>(CONTACT_ACTIONS_SELECTOR);
  if (!section || !head || !actions) return;
  const textItems = Array.from(
    head.querySelectorAll<HTMLElement>(".mask-target"),
  );
  const actionItems = Array.from(
    document.querySelectorAll<HTMLElement>(CONTACT_ACTION_ITEM_SELECTOR),
  );
  // Keep the contact panel visible through the footer zone and hide it only
  // when the scene is left or rewound before the reveal threshold.
  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;

  if (mainSceneDomState.isContactActionsVisible !== shouldShow) {
    mainSceneDomState.isContactActionsVisible = shouldShow;
    mainSceneDomState.contactActionTimers = clearTimers(
      mainSceneDomState.contactActionTimers,
    );
    const queue = shouldShow ? actionItems : actionItems.slice().reverse();
    const delayStep = shouldShow
      ? CONTACT_HEAD_TRANSITION.revealStagger
      : CONTACT_HEAD_TRANSITION.hideStagger;
    queue.forEach((item, index) => {
      const timerId = window.setTimeout(
        () => {
          item.classList.add(INIT_DOM_CLASSES.blockBase);
          item.classList.remove(INIT_DOM_CLASSES.boxHidden);
          if (shouldShow) {
            item.classList.remove("is-block-reveal-down");
            BlockReveal.reveal(item);
            return;
          }
          item.classList.remove(INIT_DOM_CLASSES.blockUp);
          item.classList.add("is-block-reveal-down");
        },
        index * delayStep * 1000,
      );
      mainSceneDomState.contactActionTimers.push(timerId);
    });
  }

  if (mainSceneDomState.isContactHeadVisible === shouldShow) return;
  mainSceneDomState.isContactHeadVisible = shouldShow;
  mainSceneDomState.contactHeadTimers = clearTimers(
    mainSceneDomState.contactHeadTimers,
  );

  if (shouldShow) {
    section.dataset.active = "true";
    head.dataset.active = "true";
    actions.dataset.active = "true";
    TextReveal.setVisibleOff(textItems);
    textItems.forEach((item, index) => {
      const timerId = window.setTimeout(
        () => {
          TextReveal.setVisibleOn(item);
        },
        index * CONTACT_HEAD_TRANSITION.revealStagger * 1000,
      );
      mainSceneDomState.contactHeadTimers.push(timerId);
    });
    return;
  }

  textItems
    .slice()
    .reverse()
    .forEach((item, index) => {
      const timerId = window.setTimeout(
        () => {
          TextReveal.setVisibleOff(item);
        },
        index * CONTACT_HEAD_TRANSITION.hideStagger * 1000,
      );
      mainSceneDomState.contactHeadTimers.push(timerId);
    });

  const hideTimerId = window.setTimeout(
    () => {
      section.dataset.active = "false";
      head.dataset.active = "false";
      actions.dataset.active = "false";
    },
    (Math.max(textItems.length - 1, 0) *
      CONTACT_HEAD_TRANSITION.hideStagger +
      CONTACT_HEAD_TRANSITION.hideSettleDuration) *
      1000,
  );
  mainSceneDomState.contactHeadTimers.push(hideTimerId);
}

function disposeContactHead(): void {
  mainSceneDomState.isContactHeadVisible = false;
  mainSceneDomState.contactHeadTimers = clearTimers(
    mainSceneDomState.contactHeadTimers,
  );
  mainSceneDomState.isContactActionsVisible = false;
  mainSceneDomState.contactActionTimers = clearTimers(
    mainSceneDomState.contactActionTimers,
  );
  const section = document.querySelector<HTMLElement>(CONTACT_SECTION_SELECTOR);
  const head = document.querySelector<HTMLElement>(CONTACT_HEAD_SELECTOR);
  const actions = document.querySelector<HTMLElement>(CONTACT_ACTIONS_SELECTOR);
  if (!section || !head || !actions) return;
  section.dataset.active = "false";
  head.dataset.active = "false";
  actions.dataset.active = "false";
  const textItems = Array.from(
    head.querySelectorAll<HTMLElement>(".mask-target"),
  );
  textItems.forEach((item) => TextReveal.setVisibleOff(item));
  const actionItems = Array.from(
    document.querySelectorAll<HTMLElement>(CONTACT_ACTION_ITEM_SELECTOR),
  );
  actionItems.forEach((item) => {
    item.classList.add(INIT_DOM_CLASSES.blockBase);
    item.classList.remove(INIT_DOM_CLASSES.blockUp, "is-block-reveal-down");
    item.classList.add(INIT_DOM_CLASSES.boxHidden);
  });
}

export const three: PageThreeConfig = {
  ...defaultThree,
  renderer: {
    ...defaultThree.renderer,
    alpha: true,
  },
  scene: {
    ...defaultThree.scene,
    background: null,
    fog: null,
  },
  camera: {
    ...defaultThree.camera,
    position: initialCameraPosition,
    fov: initialCameraFov,
  },
  cameraTarget: {
    position: initialCameraTargetPosition,
  },
  shadowMap: {
    enabled: true,
    type: defaultThree.shadowMap?.type ?? PCFSoftShadowMap,
  },
  postProcessing: {
    bloom: { ...initialPostProcessing.bloom, selective: true },
    vignette: { ...initialPostProcessing.vignette },
  },
};

const introOverlay = { tl: runIntroDomTimeline };

const MAIN_SCROLL_SCENE_SELECTORS: SceneSelectorMap<MainSceneSectionKey> = {
  intro: ".no-main-intro",
  hero: ".no-main-hero",
  story: ".no-main-story",
  who: ".no-main-who",
  whyus: ".no-main-why",
  services: ".no-main-services",
  works: '.no-main-portfolio-intro[data-scene="works"]',
  worksDetail: '.no-main-portfolio[data-scene="worksDetail"]',
  worksFinal: '.no-main-portfolio-gallery[data-scene="worksFinal"]',
