const MAIN_SCROLL_SCENE_OPTIONS: SceneProgressOptionsMap<MainSceneSectionKey> =
  {
    intro: {
      scrollSpanVh: 220,
      progressLagMs: 160,
      progressStart: 0.04,
      progressEnd: 0.96,
      progressPower: 1.02,
