      progressMode: "top",
    },
    story: {
      scrollSpanVh: 420,
      progressLagMs: 180,
      progressStart: 0.02,
      progressEnd: 0.88,
      progressPower: 1.18,
      progressMode: "top",
    },
    who: {
      scrollSpanVh: 340,
      progressLagMs: 150,
      progressStart: 0.04,
      progressEnd: 0.9,
      progressPower: 1.12,
    },
    whyus: {
