      progressPower: 1.12,
    },
    contact: {
      scrollSpanVh: 320,
      progressLagMs: 150,
      progressStart: 0.08,
      progressEnd: 0.96,
      progressPower: 1.08,
    },
  } as const;

const MAIN_BACKGROUND_TRANSITION_RULES: readonly BackgroundTransitionRule<MainTheatreSheetId>[] =
  [
    {
      from: "story",
      to: "who",
      mode: "skip",
    },
  ] as const;

const MAIN_BACKGROUND_VARIANT_BY_SHEET_ID: Readonly<
