export const SCENE_TRANSITION_VEIL_SEQUENCE = {
  cover: {
    from: 1,
    to: 0,
    duration: 1.26,
    ease: "easeInOutCubic",
  },
  hold: {
    from: 0,
    to: 0,
    duration: 0.88,
    ease: "easeInOutCubic",
  },
  reveal: {
    from: 0,
    to: 1,
    duration: 1.92,
    ease: "easeInOutCubic",
  },
  inactiveProgress: 1,
} as const;

import {
  pageAbout,
  mainBackground,
  sceneTransitionVeil,
} from "../core/setup.js";
import { ABOUT_AFTER_INTRO_AUTOPLAY_ENABLED } from "../pages/about/theatre/AboutTheatreConfig.js";
import { EnvSetup } from "../app/EnvSetup.js";
import { ScrollLock } from "../utils/ScrollLock.js";
import { HudPanel } from "../ui/HudPanel.js";
import { Panel } from "../ui/Panel.js";
import { IntroOverlay } from "../ui/IntroOverlay.js";
import { TextReveal } from "../animation/TextReveal.js";
import { BlockReveal } from "../animation/BlockReveal.js";
import { DOM_CONFIG } from "../config/dom.config.js";
import { SCENE_TRANSITION_VEIL_SEQUENCE } from "../config/transition.config.js";
import type { GsapGlobal } from "../types/gsap.types.js";
import type {
  AboutPageConfig,
  AboutSceneSectionKey,
} from "../types/about.types.js";
import type { ContactPageConfig } from "../types/contact.types.js";
import type {
  MainPageConfig,
  MainSceneSectionKey,
} from "../types/main.types.js";
import type { AppPageConfig } from "../types/runtime.types.js";
import type { IntroConfig } from "../types/core.types.js";
import type { IntroControllerDependencies } from "../types/intro.types.js";

const MAIN_FLOW = DOM_CONFIG.keys.mainFlow;
const INTRO_ACTION_CONTENT_SELECTOR =
  MAIN_FLOW?.introActionContent ?? ".no-main-intro-action__content";
const INTRO_ACTION_TO_HERO_DURATION = 1.18;
const INTRO_ACTION_TO_HERO_OFFSET_Y = -32;
const ABOUT_HERO_INTRO_TEXT_SELECTOR =
  ".no-sub-about-hero-intro .mask-target";
const ABOUT_HERO_INTRO_TOP_SELECTOR =
  ".no-sub-about-hero-intro__top.is-block-reveal";
const ABOUT_HERO_INTRO_BOTTOM_BLOCK_SELECTOR =
  ".no-sub-about-hero-intro__desc.is-block-reveal, .no-sub-about-hero-intro__info.is-block-reveal";
const ABOUT_HERO_INTRO_REVEAL_STAGGER_MS = 140;
const MAIN_DEBUG_WHO_TEXT_SELECTOR = ".no-main-who .mask-target";
const MAIN_DEBUG_WHY_TEXT_SELECTOR = ".no-main-why .mask-target";
const MAIN_DEBUG_WHY_BODY_SELECTOR = ".no-main-why__body";
const MAIN_DEBUG_WHY_VISUAL_SELECTOR = ".no-main-why__visual";
const MAIN_DEBUG_WHY_CARD_SELECTOR = ".no-main-why__card";
const MAIN_DEBUG_WORKS_DETAIL_HEAD_SELECTOR = ".no-main-portfolio__head";
const MAIN_DEBUG_WORKS_DETAIL_TEXT_SELECTOR = ".no-main-portfolio__head .mask-target";
const MAIN_DEBUG_CONTACT_HEAD_SELECTOR = ".no-main-contact__head";
const MAIN_DEBUG_CONTACT_TEXT_SELECTOR = ".no-main-contact .mask-target";

export class IntroController {
  private readonly _dependencies: IntroControllerDependencies;

  constructor(dependencies: IntroControllerDependencies) {
    this._dependencies = dependencies;
  }

  hasIntro(pageConfig: AppPageConfig, gsap: GsapGlobal | null): boolean {
    return !!this._resolveIntroOverlay(pageConfig)?.tl && !!gsap;
  }

  async runMainIntro(
    pageConfig: MainPageConfig,
    objectSetupPromise: Promise<void>,
    gsap: GsapGlobal,
  ): Promise<void> {
    const introConfig = this._resolveIntroOverlay(pageConfig);
    if (!introConfig) return;
    const isDebugMode = EnvSetup.hasQueryFlag("debug", "1");

    await this._dependencies.introFlowRuntime.run({
      introConfig,
      gsap,
      loadPromise: this._dependencies.runAfterLoad(
        pageConfig,
        objectSetupPromise,
        { deferScrollSync: true },
      ),
      root: this._dependencies.getRoot(),
      disableScrollLock: isDebugMode,
      showDebugDomState: isDebugMode,
      keepIntroActionVisible: isDebugMode,
      onAfterIntroAutoplay: isDebugMode
        ? undefined
        : async () => {
            const engine = this._dependencies.getEngine();
            if (!engine) return;
            await this._dependencies.startPageTheatreAfterIntro(engine);
          },
      onIntroDomRevealComplete: () => {
        this._dependencies.onMainIntroDomRevealComplete();
        if (isDebugMode) {
          this._dependencies.dom.setHeroHandoffVisible(true);
          TextReveal.setVisibleOn(MAIN_DEBUG_WHO_TEXT_SELECTOR);
          TextReveal.setVisibleOn(MAIN_DEBUG_WHY_TEXT_SELECTOR);
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_BODY_SELECTOR)
            ?.style.setProperty("opacity", "1");
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_BODY_SELECTOR)
            ?.style.setProperty("visibility", "visible");
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_BODY_SELECTOR)
            ?.style.setProperty("transform", "translate3d(-50%, -50%, 0)");
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_VISUAL_SELECTOR)
            ?.style.setProperty("opacity", "1");
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_VISUAL_SELECTOR)
            ?.style.setProperty("visibility", "visible");
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_VISUAL_SELECTOR)
            ?.style.setProperty("transform", "translate3d(-50%, -50%, 0)");
          document
            .querySelectorAll<HTMLElement>(MAIN_DEBUG_WHY_CARD_SELECTOR)
            .forEach((card) => {
              card.style.setProperty("--card-opacity", "1");
            });
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WORKS_DETAIL_HEAD_SELECTOR)
            ?.setAttribute("data-active", "true");
          TextReveal.setVisibleOn(MAIN_DEBUG_WORKS_DETAIL_TEXT_SELECTOR);
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_CONTACT_HEAD_SELECTOR)
            ?.setAttribute("data-active", "true");
          TextReveal.setVisibleOn(MAIN_DEBUG_CONTACT_TEXT_SELECTOR);
        }
      },
          onIntroActionAutoplay: isDebugMode
        ? undefined
        : async () => {
            const engine = this._dependencies.getEngine();
            if (!engine) return;
            const hudPanel = HudPanel.getInstance();
            hudPanel.setVisibleOn();
            hudPanel.setIntroActionFlightEnabled(false);
            this._dependencies.syncMainIntroBackground(pageConfig, "introAction", 1);
            await this._dependencies.startMainIntroActionPhaseOne(engine);
            const wasSkipped =
              await this._dependencies.introFlowRuntime.playIntroActionCountdown(
                this._dependencies.getGsap(),
              );
            if (wasSkipped) {
              hudPanel.setIntroActionFlightEnabled(false);
              hudPanel.syncFlightProgress("hero", 0, "hero");
              return;
            }
            hudPanel.startIntroActionFlight();
            await Promise.all([
              this._dependencies.startMainIntroActionPhaseTwo(engine),
              this._dependencies.introFlowRuntime.playIntroActionStorySequence(
                this._dependencies.getGsap(),
              ),
            ]);
          },
      onIntroActionTransition: isDebugMode
        ? undefined
        : async () => {
            await this._transitionMainIntroToHero(pageConfig);
          },
      onPreviewStart: isDebugMode
        ? undefined
        : this._dependencies.startPagePreviewIfNeeded,
    });
  }

  async runAboutIntro(
    pageConfig: AboutPageConfig,
    objectSetupPromise: Promise<void>,
    gsap: GsapGlobal,
  ): Promise<void> {
    const introConfig = this._resolveIntroOverlay(pageConfig);
    if (!introConfig) return;

    this._dependencies.dom.setAboutScenePlanesVisible(pageConfig, false);
    this._dependencies.dom.setAboutUiPhase("intro");

    const introRunner = new IntroOverlay(introConfig);
    let releaseAboutScrollLock: (() => void) | null = null;
    try {
      await introRunner.run({
        gsap,
        loadPromise: this._dependencies.runAfterLoad(
          pageConfig,
          objectSetupPromise,
          { deferScrollSync: true },
        ),
      });

      const engine = this._dependencies.getEngine();
      if (!engine) return;

      releaseAboutScrollLock = ScrollLock.lock({ pauseLenis: true });
      this._prepareAboutHeroIntroDomReveal();
      await this._dependencies.dom.revealAboutScenePlanes(pageConfig, gsap);
      await this._dependencies.startPageTheatreIntro(engine);
      Panel.getInstance().setVisibleOn();
      await this._playAboutHeroIntroDomReveal();
      await this._dependencies.syncAboutSceneState(pageConfig, "heroIntro", 1);
      if (ABOUT_AFTER_INTRO_AUTOPLAY_ENABLED) {
        await this._dependencies.startPageTheatreAfterIntro(engine);
        await this._dependencies.syncAboutSceneState(pageConfig, "heroSlogan", 1);
      }
      this._finishAboutIntro(pageConfig, releaseAboutScrollLock);
      releaseAboutScrollLock = null;
      await this._dependencies.startPagePreviewIfNeeded();
    } finally {
      releaseAboutScrollLock?.();
      introRunner.dispose();
    }
  }

  async runContactIntro(
    pageConfig: ContactPageConfig,
    objectSetupPromise: Promise<void>,
  ): Promise<void> {
    await this._dependencies.runAfterLoad(
      pageConfig,
      objectSetupPromise,
      { deferScrollSync: true },
    );

    const engine = this._dependencies.getEngine();
    if (!engine) {
      this._dependencies.syncContactDomState(null);
      return;
    }

    await this._dependencies.runContactIntroSequence(engine);
    Panel.getInstance().setVisibleOff();
    HudPanel.getInstance().setVisibleOff();
    ScrollLock.unlock();
  }

  private async _transitionMainIntroToHero(
    pageConfig: MainPageConfig,
  ): Promise<void> {
    this._dependencies.onMainIntroTransitionStateChange(true);
    try {
      this._dependencies.introHandoffRuntime.setHeroTextVisible(false);
      this._dependencies.dom.setHeroHandoffVisible(false);
      await this._dependencies.introHandoffRuntime.transitionToHero({
        gsap: this._dependencies.getGsap(),
        transitionRuntime: this._dependencies.sceneTransitionRuntime,
        veil: this._dependencies.resolveTransitionVeil(sceneTransitionVeil),
        steps: [
          SCENE_TRANSITION_VEIL_SEQUENCE.cover,
          SCENE_TRANSITION_VEIL_SEQUENCE.reveal,
        ],
        inactiveProgress: SCENE_TRANSITION_VEIL_SEQUENCE.inactiveProgress,
        actionContentSelector: INTRO_ACTION_CONTENT_SELECTOR,
        actionContentOffsetY: INTRO_ACTION_TO_HERO_OFFSET_Y,
        actionContentDuration: INTRO_ACTION_TO_HERO_DURATION,
        onCoverComplete: async () => {
          this._dependencies
            .getEngine()
            ?.getBackgroundManager()
            ?.startTransition(mainBackground);
          await this._dependencies.syncMainSceneState(pageConfig, "hero", 0);
        },
      });
      this._dependencies.dom.setHeroHandoffVisible(true);
      await this._dependencies.introHandoffRuntime.playHeroTextRise();
      this._finishMainIntro(pageConfig);
    } finally {
      this._dependencies.onMainIntroTransitionStateChange(false);
    }
  }

  private _finishMainIntro(pageConfig: MainPageConfig): void {
    HudPanel.getInstance().setVisibleOn();
    Panel.getInstance().setVisibleOff();
    window.scrollTo({ top: 0, behavior: "auto" });
    this._dependencies.introFlowRuntime.releaseScrollLock();
    this._dependencies.startMainScrollSyncAfterIntro(pageConfig);
  }

  private _finishAboutIntro(
    pageConfig: AboutPageConfig,
    releaseScrollLock: (() => void) | null,
  ): void {
    HudPanel.getInstance().setVisibleOff();
    this._dependencies.startAboutScrollSyncAfterIntro(pageConfig);
    releaseScrollLock?.();
    window.requestAnimationFrame(() => {
      this._dependencies.dom.scrollToAboutSceneProgress(pageConfig, "heroIntro", 0);
    });
  }

  private _resolveIntroOverlay(pageConfig: AppPageConfig): IntroConfig | null {
    return pageConfig.introOverlay ?? pageConfig.intro ?? null;
  }

  private _prepareAboutHeroIntroDomReveal(): void {
    TextReveal.setVisibleOff(ABOUT_HERO_INTRO_TEXT_SELECTOR);
    BlockReveal.hide(ABOUT_HERO_INTRO_TOP_SELECTOR);
    BlockReveal.hide(ABOUT_HERO_INTRO_BOTTOM_BLOCK_SELECTOR);
  }

  private async _playAboutHeroIntroDomReveal(): Promise<void> {
    BlockReveal.reveal(ABOUT_HERO_INTRO_TOP_SELECTOR);
    const textItems = Array.from(
      document.querySelectorAll<HTMLElement>(ABOUT_HERO_INTRO_TEXT_SELECTOR),
    );
    if (textItems.length > 0) {
      await new Promise<void>((resolve) => {
        let completed = 0;
        textItems.forEach((item, index) => {
          window.setTimeout(() => {
            TextReveal.riseUp(item);
            completed += 1;
            if (completed === textItems.length) {
              resolve();
            }
          }, index * ABOUT_HERO_INTRO_REVEAL_STAGGER_MS);
        });
      });
    }
    BlockReveal.reveal(ABOUT_HERO_INTRO_BOTTOM_BLOCK_SELECTOR);
    await new Promise<void>((resolve) => {
      window.setTimeout(resolve, ABOUT_HERO_INTRO_REVEAL_STAGGER_MS * 2);
    });
  }
}

import * as THREE from "three";
import { SceneObject } from "../../core/SceneObject.js";
import { Helpers } from "../../utils/Helpers.js";
import type {
  TransitionVeilTweenProps,
} from "../../types/object.types.js";
import type { TransitionVeilObjectOptions } from "../../types/object-visual.types.js";
import type {
  ShaderUniformRecord,
  TransitionVeilRuntimePort,
  TransitionVeilRuntimeState,
} from "../../types/object-runtime.types.js";
import transitionVeilVertexShader from "../../../shaders/who-reveal/vertex.glsl?raw";
import transitionVeilFragmentShader from "../../../shaders/who-reveal/fragment.glsl?raw";

const TRANSITION_VEIL_RENDER_ORDER = 2200;
const TRANSITION_VEIL_DEFAULT_OPACITY = 0.96;
const TRANSITION_VEIL_DEFAULT_NOISE_STRENGTH = 1;
const TRANSITION_VEIL_DEFAULT_REVEAL_SOFTNESS = 0.24;
const TRANSITION_VEIL_DEFAULT_SIZE_X = 2.4;
const TRANSITION_VEIL_DEFAULT_SIZE_Y = 1.8;
const TRANSITION_VEIL_DEFAULT_COLOR_DARK = 0xc7d3de;
const TRANSITION_VEIL_DEFAULT_COLOR_LIGHT = 0xfbfdff;
const TRANSITION_VEIL_TIME_EPSILON = 0.0001;
const TRANSITION_VEIL_PROGRESS_EPSILON = 0.0001;
const TRANSITION_VEIL_DEFAULT_DISTANCE = 16;
const TRANSITION_VEIL_COVER_OVERSCAN = 1.35;
const TRANSITION_VEIL_CAMERA_FORWARD = new THREE.Vector3();
const TRANSITION_VEIL_CAMERA_RIGHT = new THREE.Vector3();
const TRANSITION_VEIL_CAMERA_UP = new THREE.Vector3();
const TRANSITION_VEIL_OFFSET = new THREE.Vector3();

export class TransitionVeil
  extends SceneObject<TransitionVeilTweenProps>
  implements TransitionVeilRuntimePort
{
  private _options: Partial<TransitionVeilObjectOptions> = {};
  private _runtimeState: TransitionVeilRuntimeState = { active: false, progress: 0 };
  private _mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial> | null =
    null;
  private _material: THREE.ShaderMaterial | null = null;
  private _noiseTexture: THREE.Texture | null = null;
  private _perlinTexture: THREE.Texture | null = null;
  private _elapsedTime = 0;
  private _lastActive = false;
  private _lastProgress = Number.NaN;
  private _lastResolutionWidth = 0;
  private _lastResolutionHeight = 0;
  private _lastTimeUniform = Number.NaN;

  setOptions(props: Partial<TransitionVeilObjectOptions> | undefined): this {
    if (!props) return this;
    this._options = {
      ...this._options,
      ...props,
      position: { ...this._options.position, ...props.position },
      rotation: { ...this._options.rotation, ...props.rotation },
      scale: { ...this._options.scale, ...props.scale },
      plane: { ...this._options.plane, ...props.plane },
      shader: {
        ...this._options.shader,
        ...props.shader,
        textures: {
          ...this._options.shader?.textures,
          ...props.shader?.textures,
        },
        size: {
          ...this._options.shader?.size,
          ...props.shader?.size,
        },
      },
    };
    return this;
  }

  setRuntimeState(state: Partial<TransitionVeilRuntimeState>): void {
    const prevActive = this._runtimeState.active;
    const prevProgress = this._runtimeState.progress;
    this._runtimeState = {
      ...this._runtimeState,
      ...state,
    };
    const nextActive = this._runtimeState.active;
    const nextProgress = this._runtimeState.progress ?? 0;
    if (prevActive !== nextActive) {
      console.log(`[VEIL:mesh] active changed  ${String(prevActive)} → ${String(nextActive)}  progress=${nextProgress.toFixed(4)}`);
    } else if (
      Math.abs((prevProgress ?? 0) - nextProgress) > 0.05
    ) {
      console.log(`[VEIL:mesh] progress jump  ${(prevProgress ?? 0).toFixed(4)} → ${nextProgress.toFixed(4)}  active=${String(nextActive)}`);
    }
    this._syncVisibility();
    if (!this._runtimeState.active) return;
    this._applyRuntimeUniforms();
  }

  getRuntimeState(): TransitionVeilRuntimeState {
    return { ...this._runtimeState };
  }

  override getAnimationTarget(): THREE.Object3D | null {
    return this.getTimelineRoot();
  }

  override getBloomEnabled(): boolean {
    return false;
  }

  override getTweenApplyMode(): "mergeAndSync" {
    return "mergeAndSync";
  }

  protected override getOptions(): Record<string, unknown> {
    return this._options;
  }

  protected override mergeOptionsFromTimeline(
    vars: Partial<TransitionVeilTweenProps>,
  ): void {
    if (vars.position) this._options.position = { ...this._options.position, ...vars.position };
    if (vars.rotation) this._options.rotation = { ...this._options.rotation, ...vars.rotation };
    if (vars.scale) this._options.scale = { ...this._options.scale, ...vars.scale };
    if (typeof vars.visible === "boolean") this._options.visible = vars.visible;
    if (typeof vars.progress === "number") this._runtimeState.progress = vars.progress;
    if (typeof vars.active === "boolean") this._runtimeState.active = vars.active;
  }

  protected override applyVisibility(visible: boolean): void {
    const root = this.getTimelineRoot();
    if (!root) return;
    root.visible = visible && (this._runtimeState.active ?? false);
  }

  protected override syncFromOptions(): void {
    this._applyStaticUniforms();
    this._syncVisibility();
  }

  override async runObject(): Promise<void> {
    const scene = this._context?.scene;
    if (!scene) return;

    const root = this.ensureTimelineRoot("transitionVeilRoot");
    if (!root) return;
    await this._loadTextures();

    this._material = this._createMaterial();
    this._mesh = new THREE.Mesh(this._createGeometry(), this._material);
    this._mesh.frustumCulled = false;
    this._mesh.renderOrder = TRANSITION_VEIL_RENDER_ORDER;
    root.add(this._mesh);

    this._followCamera();
    this._applyStaticUniforms();
    this._applyRuntimeUniforms();
    this._syncVisibility();
  }

  override runUpdate(deltaTime: number): void {
    if (this._disposed) return;
    this._followCamera();
    if (!this._runtimeState.active) return;
    this._elapsedTime += Number.isFinite(deltaTime) ? Math.max(0, deltaTime) : 0;
    this._applyRuntimeUniforms();
  }

  override dispose(): void {
    this._mesh?.geometry.dispose();
    this._material?.dispose();
    this._noiseTexture?.dispose();
    this._perlinTexture?.dispose();
    this._mesh = null;
    this._material = null;
    this._noiseTexture = null;
    this._perlinTexture = null;
    super.dispose();
  }

  private async _loadTextures(): Promise<void> {
    const loadTexture = this._context?.loadTexture;
    const textures = this._options.shader?.textures;
    const perlinTextureUrl = textures?.perlinTextureUrl?.trim();
    const noiseTextureUrl = textures?.noiseTextureUrl?.trim();
    if (!loadTexture || !perlinTextureUrl || !noiseTextureUrl) return;

    const [perlinTexture, noiseTexture] = await Promise.all([
      loadTexture(this.resolveAssetPath(perlinTextureUrl)),
      loadTexture(this.resolveAssetPath(noiseTextureUrl)),
    ]);
    this._prepareTexture(perlinTexture);
    this._prepareTexture(noiseTexture);
    this._perlinTexture = perlinTexture;
    this._noiseTexture = noiseTexture;
    this._context?.prepareTexture?.(perlinTexture);
    this._context?.prepareTexture?.(noiseTexture);
  }

  private _prepareTexture(texture: THREE.Texture): void {
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    texture.needsUpdate = true;
  }

  private _createGeometry(): THREE.PlaneGeometry {
    return new THREE.PlaneGeometry(1, 1, 1, 1);
  }

  private _createMaterial(): THREE.ShaderMaterial {
    return new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uProgress: { value: 0 },
        uOpacity: {
          value: this._finiteOr(
            this._options.shader?.opacity,
            TRANSITION_VEIL_DEFAULT_OPACITY,
          ),
        },
        uNoiseStrength: {
          value: this._finiteOr(
            this._options.shader?.noiseStrength,
            TRANSITION_VEIL_DEFAULT_NOISE_STRENGTH,
          ),
        },
        uRevealSoftness: {
          value: this._finiteOr(
            this._options.shader?.revealSoftness,
            TRANSITION_VEIL_DEFAULT_REVEAL_SOFTNESS,
          ),
        },
        uResolution: { value: new THREE.Vector2(1, 1) },
        uSize: {
          value: new THREE.Vector2(
            this._finiteOr(
              this._options.shader?.size?.x,
              TRANSITION_VEIL_DEFAULT_SIZE_X,
            ),
            this._finiteOr(
              this._options.shader?.size?.y,
              TRANSITION_VEIL_DEFAULT_SIZE_Y,
            ),
          ),
        },
        uDarkColor: {
          value: new THREE.Color(TRANSITION_VEIL_DEFAULT_COLOR_DARK),
        },
        uLightColor: {
          value: new THREE.Color(TRANSITION_VEIL_DEFAULT_COLOR_LIGHT),
        },
        tPerlin: { value: this._perlinTexture },
        tNoise: { value: this._noiseTexture },
      },
      vertexShader: transitionVeilVertexShader,
      fragmentShader: transitionVeilFragmentShader,
      transparent: true,
      depthWrite: false,
      depthTest: false,
      side: THREE.DoubleSide,
    });
  }

  private _applyStaticUniforms(): void {
    const uniforms = this._material?.uniforms as ShaderUniformRecord | undefined;
    if (!uniforms) return;
    this._followCamera();
    this._setUniformNumber(
      uniforms,
      "uOpacity",
      this._finiteOr(
        this._options.shader?.opacity,
        TRANSITION_VEIL_DEFAULT_OPACITY,
      ),
    );
    this._setUniformNumber(
      uniforms,
      "uNoiseStrength",
      this._finiteOr(
        this._options.shader?.noiseStrength,
        TRANSITION_VEIL_DEFAULT_NOISE_STRENGTH,
      ),
    );
    this._setUniformNumber(
      uniforms,
      "uRevealSoftness",
      this._finiteOr(
        this._options.shader?.revealSoftness,
        TRANSITION_VEIL_DEFAULT_REVEAL_SOFTNESS,
      ),
    );
    const size = uniforms.uSize?.value;
    if (!(size instanceof THREE.Vector2)) return;
    size.set(
      this._finiteOr(
        this._options.shader?.size?.x,
        TRANSITION_VEIL_DEFAULT_SIZE_X,
      ),
      this._finiteOr(
        this._options.shader?.size?.y,
        TRANSITION_VEIL_DEFAULT_SIZE_Y,
      ),
    );
  }

  private _applyRuntimeUniforms(): void {
    const uniforms = this._material?.uniforms as ShaderUniformRecord | undefined;
    if (!uniforms) return;
    const isActive = this._runtimeState.active ?? false;
    const progress = Helpers.clamp01(
      this._runtimeState.progress ?? this._options.progress ?? 0,
    );
    if (
      isActive ||
      this._lastActive !== isActive ||
      Math.abs(progress - this._lastProgress) > TRANSITION_VEIL_PROGRESS_EPSILON
    ) {
      this._setUniformNumber(uniforms, "uProgress", progress);
      this._lastProgress = progress;
    }
    if (
      isActive &&
      Math.abs(this._elapsedTime - this._lastTimeUniform) > TRANSITION_VEIL_TIME_EPSILON
    ) {
      this._setUniformNumber(uniforms, "uTime", this._elapsedTime);
      this._lastTimeUniform = this._elapsedTime;
    }
    const resolution = uniforms.uResolution?.value;
    const renderer = this._context?.renderer;
    const width = renderer?.domElement?.width;
    const height = renderer?.domElement?.height;
    if (!(resolution instanceof THREE.Vector2)) return;
    if (!Number.isFinite(width) || !Number.isFinite(height)) return;
    const nextWidth = width as number;
    const nextHeight = height as number;
    if (
      nextWidth !== this._lastResolutionWidth ||
      nextHeight !== this._lastResolutionHeight
    ) {
      resolution.set(nextWidth, nextHeight);
      this._lastResolutionWidth = nextWidth;
      this._lastResolutionHeight = nextHeight;
    }
    this._lastActive = isActive;
  }

  private _syncVisibility(): void {
    const root = this.getTimelineRoot();
    if (!root) return;
    root.visible = this._options.visible !== false && (this._runtimeState.active ?? false);
  }

  private _followCamera(): void {
    const root = this.getTimelineRoot();
    const camera = this._context?.camera;
    if (!root || !camera) return;

    const distance = this._resolveDistance();
    camera.getWorldDirection(TRANSITION_VEIL_CAMERA_FORWARD);
    root.quaternion.copy(camera.quaternion);
    root.position.copy(camera.position).addScaledVector(
      TRANSITION_VEIL_CAMERA_FORWARD,
      distance,
    );

    TRANSITION_VEIL_CAMERA_RIGHT.set(1, 0, 0).applyQuaternion(camera.quaternion);
    TRANSITION_VEIL_CAMERA_UP.set(0, 1, 0).applyQuaternion(camera.quaternion);
    TRANSITION_VEIL_OFFSET.set(
      this._finiteOr(this._options.position?.x, 0),
      this._finiteOr(this._options.position?.y, 0),
      this._finiteOr(this._options.position?.z, 0),
    );
    root.position
      .addScaledVector(TRANSITION_VEIL_CAMERA_RIGHT, TRANSITION_VEIL_OFFSET.x)
      .addScaledVector(TRANSITION_VEIL_CAMERA_UP, TRANSITION_VEIL_OFFSET.y)
      .addScaledVector(TRANSITION_VEIL_CAMERA_FORWARD, TRANSITION_VEIL_OFFSET.z);

    const coverSize = this._resolveCoverSize(camera, distance);
    const planeWidth = this._finiteOr(this._options.plane?.width, coverSize.width);
    const planeHeight = this._finiteOr(this._options.plane?.height, coverSize.height);
    root.scale.set(
      Math.max(planeWidth, coverSize.width),
      Math.max(planeHeight, coverSize.height),
      1,
    );
  }

  private _resolveDistance(): number {
    return this._finiteOr(
      this._options.plane?.distance,
      TRANSITION_VEIL_DEFAULT_DISTANCE,
    );
  }

  private _resolveCoverSize(
    camera: THREE.Camera,
    distance: number,
  ): { width: number; height: number } {
    if (camera instanceof THREE.PerspectiveCamera) {
      const verticalFov = THREE.MathUtils.degToRad(camera.fov);
      const height =
        2 * Math.tan(verticalFov * 0.5) * distance * TRANSITION_VEIL_COVER_OVERSCAN;
      return {
        width: height * camera.aspect,
        height,
      };
    }
    if (camera instanceof THREE.OrthographicCamera) {
      const width =
        ((camera.right - camera.left) / Math.max(camera.zoom, 0.0001)) *
        TRANSITION_VEIL_COVER_OVERSCAN;
      const height =
        ((camera.top - camera.bottom) / Math.max(camera.zoom, 0.0001)) *
        TRANSITION_VEIL_COVER_OVERSCAN;
      return { width, height };
    }
    return {
      width: this._finiteOr(this._options.plane?.width, 1) * TRANSITION_VEIL_COVER_OVERSCAN,
      height: this._finiteOr(this._options.plane?.height, 1) * TRANSITION_VEIL_COVER_OVERSCAN,
    };
  }

  private _setUniformNumber(
    uniforms: ShaderUniformRecord,
    key: string,
    value: number,
  ): void {
    const target = uniforms[key];
    if (!target) return;
    target.value = value;
  }

  private _finiteOr(value: number | undefined, fallback: number): number {
    return Number.isFinite(value) ? (value as number) : fallback;
  }
}

import type { GsapGlobal } from "../types/gsap.types.js";
import { Helpers } from "../utils/Helpers.js";
import type {
  SceneTransitionPlayOptions,
  SceneTransitionStep,
} from "../types/runtime.types.js";
import type {
  TransitionEaseKey,
  TransitionVeilRuntimePort,
} from "../types/object-runtime.types.js";

const DEFAULT_INACTIVE_PROGRESS = 1;

export class SceneTransitionRuntime {
  syncVeil(veil: TransitionVeilRuntimePort | null, progress: number): void {
    if (!veil) return;
    veil.setRuntimeState({
      active: true,
      progress: Helpers.clamp01(progress),
    });
  }

  resetVeil(
    veil: TransitionVeilRuntimePort | null,
    inactiveProgress = DEFAULT_INACTIVE_PROGRESS,
  ): void {
    if (!veil) return;
    veil.setRuntimeState({
      active: false,
      progress: Helpers.clamp01(inactiveProgress),
    });
  }

  async play(
    options: SceneTransitionPlayOptions,
    gsap: GsapGlobal | null,
  ): Promise<void> {
    const { veil, steps, onStepComplete, initialState, finalState } = options;
    console.group("[VEIL:play] transition start");
    console.log("steps:", steps.map((s, i) => `[${i}] ${s.from}→${s.to} ${s.duration}s`));
    console.log("initialState:", initialState, "finalState:", finalState);

    if (!veil || steps.length === 0) {
      console.warn("[VEIL:play] no veil or no steps — skipping");
      console.groupEnd();
      if (onStepComplete) await onStepComplete(0);
      return;
    }

    veil.setRuntimeState({
      active: true,
      progress: Helpers.clamp01(initialState?.progress ?? steps[0]?.from ?? 0),
      ...initialState,
    });

    if (!gsap) {
      for (let index = 0; index < steps.length; index += 1) {
        veil.setRuntimeState({
          active: true,
          progress: Helpers.clamp01(steps[index].to),
        });
        if (onStepComplete) await onStepComplete(index);
      }
      veil.setRuntimeState({
        active: false,
        progress: Helpers.clamp01(
          finalState?.progress ?? steps[steps.length - 1]?.to ?? 1,
        ),
        ...finalState,
      });
      console.groupEnd();
      return;
    }

    for (let index = 0; index < steps.length; index += 1) {
      await this._playStep(gsap, veil, steps[index], index);
      if (onStepComplete) await onStepComplete(index);
    }

    veil.setRuntimeState({
      active: false,
      progress: Helpers.clamp01(
        finalState?.progress ?? steps[steps.length - 1]?.to ?? 1,
      ),
      ...finalState,
    });
    console.log("[VEIL:play] transition complete — finalState applied");
    console.groupEnd();
  }

  private async _playStep(
    gsap: GsapGlobal,
    veil: TransitionVeilRuntimePort,
    step: SceneTransitionStep,
    stepIndex = 0,
  ): Promise<void> {
    const stepLabel = stepIndex === 0 ? "cover" : stepIndex === 1 ? "hold" : "reveal";
    const t0 = performance.now();
    console.log(`[VEIL:step] ${stepLabel} START  from=${step.from} to=${step.to} dur=${step.duration}s`);

    const state = { progress: Helpers.clamp01(step.from) };
    veil.setRuntimeState({
      active: true,
      progress: state.progress,
    });

    await new Promise<void>((resolve) => {
      gsap.to(state, {
        progress: Helpers.clamp01(step.to),
        duration: Math.max(0, step.duration),
        ease: this._resolveEase(step.ease),
        onUpdate: () => {
          veil.setRuntimeState({
            active: true,
            progress: state.progress,
          });
        },
        onComplete: () => resolve(),
      });
    });

    console.log(`[VEIL:step] ${stepLabel} DONE   elapsed=${((performance.now() - t0) / 1000).toFixed(2)}s  finalProgress=${state.progress.toFixed(4)}`);
  }

  private _resolveEase(ease: TransitionEaseKey | undefined): string {
    if (ease === "easeInOutCubic") return "power2.inOut";
    return "none";
  }
}

