21	float veilFbm(sampler2D textureSampler, vec2 uv) {
22	  float amplitude = 0.5;
23	  float value = 0.0;
24	  vec2 currentUv = uv;
25	  for (int index = 0; index < 4; index += 1) {
26	    value += texture2D(textureSampler, currentUv).r * amplitude;
27	    currentUv *= 2.03;
28	    amplitude *= 0.5;
29	  }
30	  return value;
31	}
32	
33	float veilRidgedNoise(sampler2D textureSampler, vec2 uv) {
34	  float baseValue = veilFbm(textureSampler, uv);
35	  return 1.0 - abs(baseValue * 2.0 - 1.0);
36	}
37	
38	void main() {
39	  vec2 safeResolution = max(uResolution, vec2(1.0));
40	  vec2 screenUv = gl_FragCoord.xy / safeResolution;
41	  float time = uTime * 0.18;
42	  vec2 flowUv = vUv * uSize;
43	  vec2 driftUv = flowUv;
44	  driftUv.x += sin(time * 0.42 + vUv.y * 4.8) * 0.035;
45	  driftUv.y += cos(time * 0.34 + vUv.x * 5.4) * 0.022;
46	  flowUv = mix(flowUv, driftUv, 0.72);
47	  vec2 largeCloudUv = flowUv * 0.05 + vec2(0.004 * time, -0.01 * time);
48	  vec2 midCloudUv = flowUv * 0.14 + vec2(-0.009 * time, 0.016 * time);
49	  vec2 fineCloudUv = flowUv * 0.33 + vec2(0.018 * time, -0.014 * time);
50	  float largeCloudNoise = veilFbm(tNoise, largeCloudUv);
51	  float largeCloudDetail = veilFbm(tPerlin, largeCloudUv * 1.6);
52	  float layeredCloudBase = smoothstep(
53	    0.42,
54	    0.88,
55	    largeCloudNoise * 0.62 + largeCloudDetail * 0.38
56	  );
57	  float layeredCloudRidge = veilRidgedNoise(tPerlin, midCloudUv * 0.82);
58	  float layeredCloudShadow = veilRidgedNoise(tNoise, fineCloudUv * 0.74);
59	  float cloudGapMask = 1.0 - smoothstep(0.36, 0.74, largeCloudNoise);
60	  float cloudBodyMask = smoothstep(0.48, 0.86, largeCloudNoise + layeredCloudRidge * 0.32);
61	  float cloudShadowMask = smoothstep(0.54, 0.92, layeredCloudShadow * largeCloudDetail);
62	  float baseNoise = texture2D(
63	    tNoise,
64	    flowUv * 0.18 + vec2(0.01 * time, -0.028 * time)
65	  ).r;
