84	    flowUv * 3.4 + vec2(-0.04 * time, 0.028 * time)
85	  ).r;
86	  float plumeNoise = texture2D(
87	    tNoise,
88	    flowUv * 0.62 + vec2(0.014 * time, -0.01 * time)
89	  ).b;
90	  float erosionNoise = texture2D(
91	    tPerlin,
