95	  vec2 distortedUv = vUv;
96	  distortedUv.x += (detailNoise - 0.5) * 0.11 * uNoiseStrength;
97	  distortedUv.y += (bodyNoise - 0.5) * 0.24 * uNoiseStrength;
98	  distortedUv.x += (curlNoise - 0.5) * 0.072 * uNoiseStrength;
99	  distortedUv.y += (plumeNoise - 0.5) * 0.06 * uNoiseStrength;
