151	  density *= mix(1.08, 0.72, erosion * (1.0 - textureLayer * 0.48));
152	  density *= mix(0.88, 1.08, layeredCloudShadow);
153	  density *= mix(1.0, 0.36, cloudGapMask);
154	  density += smoothstep(0.6, 0.9, curlNoise) * 0.08;
155	  density += smoothstep(0.68, 0.94, microNoise) * 0.05;
156	  density += smoothstep(0.58, 0.86, plumeNoise) * 0.08;
157	  density += smoothstep(0.56, 0.84, erosionNoise) * 0.06;
158	  density += smoothstep(0.54, 0.9, layeredCloudRidge) * 0.12;
159	  density += cloudBodyMask * 0.18;
160	  density = smoothstep(0.24, 0.90, density);
161	  density = saturateFloat(density);
162	
163	  vec2 centeredUv = screenUv - 0.5;
164	  centeredUv.x *= safeResolution.x / safeResolution.y;
165	  float centerDistance = length(centeredUv);
