override async runObject(): Promise<void> {
  const scene = this._context?.scene;
  if (!scene) return;

  const root = this.ensureTimelineRoot(this._getLayerLabel());
  if (!root) return;
  root.name = this._getLayerLabel();

  this._clearRuntime();
  await this._prepareShaderTextures();

  this._material = this._createMaterial();
  this._mesh = new THREE.Mesh(
    this._createCurvedPlaneGeometry(),
    this._material,
  );
  this._mesh.name = `${this._getLayerLabel()}.mesh`;
  this._mesh.frustumCulled = false;
  this._mesh.renderOrder = CLOUD_PLANE_RENDER_ORDER;
  root.add(this._mesh);

  this._applyBaseTransform();
  this._applyStaticUniforms();
  this._applyDynamicUniforms();
}

override runUpdate(deltaTime: number): void {
  this._elapsedTime += Number.isFinite(deltaTime)
    ? Math.max(0, deltaTime)
    : 0;
  this._updateMouseTexture();
  this._applyDynamicUniforms();
}

override dispose(): void {
  this._clearRuntime();
  super.dispose();
}

private async _prepareShaderTextures(): Promise<void> {
  this._disposeTextures();
  const ctx = this._context;
  const textures = this._options.shader?.textures;
  if (!ctx?.loadTexture || !textures) return;
  const perlinTextureUrl = textures.perlinTextureUrl?.trim();
  const noiseTextureUrl = textures.noiseTextureUrl?.trim();
  if (!perlinTextureUrl || !noiseTextureUrl) return;
  const [perlinTexture, noiseTexture] = await Promise.all([
    this._loadSharedTexture(
      this.resolveAssetPath(perlinTextureUrl),
      this._prepareRepeatTexture,
    ),
    this._loadSharedTexture(
      this.resolveAssetPath(noiseTextureUrl),
      this._prepareRepeatTexture,
    ),
  ]);
  this._perlinTexture = perlinTexture;
  this._noiseTexture = noiseTexture;
  this._createMouseTexture();
  const perlinTextureRef = this._perlinTexture;
  const noiseTextureRef = this._noiseTexture;
  const mouseTextureRef = this._mouseTexture;
  if (perlinTextureRef) ctx.prepareTexture?.(perlinTextureRef);
  if (noiseTextureRef) ctx.prepareTexture?.(noiseTextureRef);
  if (mouseTextureRef) ctx.prepareTexture?.(mouseTextureRef);
}

private _prepareRepeatTexture(texture: THREE.Texture): THREE.Texture {
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearMipmapLinearFilter;
  texture.needsUpdate = true;
  return texture;
}

private _createMaterial(): THREE.ShaderMaterial {
  const shader = this._options.shader;
  return new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uRatio: { value: this._finiteOr(shader?.ratio, 2) },
      uChapter: {
        value: this._finiteOr(
          shader?.chapter,
          this._finiteOr(this._options.chapter, 0),
        ),
      },
      uTransition: {
        value: this._finiteOr(
          shader?.transition,
          this._finiteOr(this._options.transition, 0),
        ),
      },
      uOpacity: { value: this._finiteOr(shader?.opacity, 0.16) },
      uRocketInfluence: { value: 0 },
      uRocketRadius: { value: CLOUD_ROCKET_EFFECT_RADIUS },
      uRocketUv: { value: new THREE.Vector2(0.5, 0.5) },
      uDarkColor: { value: new THREE.Color(DEFAULT_CLOUD_DARK_COLOR) },

import * as THREE from "three";
import { SceneObject } from "../../core/SceneObject.js";
import type { SceneObjectContext } from "../../types/engine.types.js";
import type { GravityBallsObjectOptions } from "../../types/object.types.js";

interface SphereInfo {
  ID: number;
  startX: number;
  startY: number;
  startZ: number;
  vx: number;
  vy: number;
  vz: number;
  rotDir: number;
  shrinkRate: number;
  sphere: THREE.Sprite;
  material: THREE.SpriteMaterial;
}

type ResolvedOpts = {
  attachTo: string;
  spawnOffset: { x?: number; y?: number; z?: number };
  colors: string[];
  dotsPerInterval: number;
  physicsScale: number;
};

const FADE_START_SCALE = 0.65;
const SMOKE_Z_DRIFT = 0.002;
const SMOKE_SPREAD = 1.005;
const MIN_INIT_SCALE = 0.4;
const MAX_INIT_SCALE = 1.0;
const LIFETIME_TICKS = 150;

const DEFAULT_TEXTURE_URLS = [
  "/resource/images/texture/smoke/smoke_01.png",
  "/resource/images/texture/rocket/smoke.png",
];

const DEFAULTS = {
  attachTo: "rocket",
  spawnOffset: { x: 0 as number, y: -0.34 as number, z: 0 as number },
  colors: ["#FFFFFF", "#F5F5F5", "#EEEEEE"] as string[],
  dotsPerInterval: 3,
  physicsScale: 0.006,
};

export class GravityBalls extends SceneObject<Record<string, never>> {
  private readonly _balls = new Map<number, SphereInfo>();
  private _idx = 0;
  private _accumMs = 0;
  private readonly _spawnPt = new THREE.Vector3();
  private _opts: GravityBallsObjectOptions = {};
  private _baseMats: THREE.SpriteMaterial[] = [];

  setOptions(props: Partial<GravityBallsObjectOptions> | undefined): this {
    if (props) this._opts = { ...this._opts, ...props };
    return this;
  }

  protected override getOptions(): Record<string, unknown> {
    return this._opts as Record<string, unknown>;
  }

  override async runObject(): Promise<void> {
    const ctx = this._context;
    if (!ctx) return;

    const urls: string[] =
      this._opts.textureUrls?.length ? this._opts.textureUrls
      : this._opts.textureUrl ? [this._opts.textureUrl]
      : DEFAULT_TEXTURE_URLS;

    const textures = await Promise.all(
      urls.map(async (url): Promise<THREE.Texture | null> => {
        if (!url || !ctx.loadTexture) return null;
        try { return await ctx.loadTexture(this.resolveAssetPath(url)); }
        catch { return null; }
      }),
    );

    this._baseMats = textures.length > 0
      ? textures.map(tex => new THREE.SpriteMaterial({
          map: tex ?? null,
          transparent: true,
          depthWrite: false,
          opacity: 0.8,
        }))
      : [new THREE.SpriteMaterial({ transparent: true, depthWrite: false, opacity: 0.8 })];

    this._applyOptionVisibility();
  }

  override runUpdate(delta: number): void {
    const ctx = this._context;
    if (!ctx || this._disposed) return;

    this._accumMs += delta * 1000;
    if (this._accumMs >= 15) {
      this._accumMs -= 15;
      this._tick(ctx);
    }
  }

  private _tick(ctx: SceneObjectContext): void {
    const o = this._resolve();

    if (o.attachTo) {
      const rkt = ctx.getObject(o.attachTo);
      if (rkt instanceof THREE.Object3D) {
        rkt.getWorldPosition(this._spawnPt);
        this._spawnPt.x += o.spawnOffset.x ?? 0;
        this._spawnPt.y += o.spawnOffset.y ?? 0;
        this._spawnPt.z += o.spawnOffset.z ?? 0;
      }
    }

    for (let i = 0; i < o.dotsPerInterval; i++) this._spawn(ctx, o);

    const dead: number[] = [];
    this._balls.forEach((b, id) => { if (this._step(b)) dead.push(id); });
    for (const id of dead) this._balls.delete(id);
  }

  private _spawn(ctx: SceneObjectContext, o: ResolvedOpts): void {
    if (this._baseMats.length === 0) return;

    const s = o.physicsScale;
    const baseMat = this._baseMats[Math.floor(Math.random() * this._baseMats.length)];
    const mat = baseMat.clone();

    const color = o.colors[this._rnd(0, o.colors.length)] ?? o.colors[0];
    mat.color.set(color);
    mat.rotation = Math.random() * Math.PI * 2;

    const initScale = MIN_INIT_SCALE + Math.random() * (MAX_INIT_SCALE - MIN_INIT_SCALE);
    const shrinkRate = -(initScale - 0.1) / LIFETIME_TICKS;

    const isXNeg = this._rnd(1, 2) === 1;
    const isZNeg = this._rnd(1, 2) === 1;

    const sprite = new THREE.Sprite(mat);
    sprite.scale.setScalar(initScale);

    const info: SphereInfo = {
      ID: ++this._idx,
      startX: this._spawnPt.x,
      startY: this._spawnPt.y,
      startZ: this._spawnPt.z,
      vx: isXNeg ? this._rnd(0, 50) * -0.15 * s : this._rnd(0, 50) * 0.15 * s,
      vy: this._rnd(-10, 20) * s,
      vz: isZNeg ? this._rnd(-25, 25) * -0.4 * s : this._rnd(-25, 25) * 0.4 * s,
      rotDir: (Math.random() < 0.5 ? 1 : -1) * (0.003 + Math.random() * 0.006),
      shrinkRate,
      sphere: sprite,
      material: mat,
    };

    ctx.scene.add(sprite);
    this._balls.set(info.ID, info);
  }

  private _step(b: SphereInfo): boolean {
    const sp = b.sphere;

    sp.scale.x += b.shrinkRate;
    sp.scale.y += b.shrinkRate;

    b.startX += b.vx * 0.6;
    b.startY -= b.vy * 0.5;
    b.startZ -= b.vz * 0.6;
    sp.position.x = b.startX;
    sp.position.y = b.startY;
    sp.position.z = b.startZ;

    b.material.rotation += b.rotDir;

    if (sp.scale.y < FADE_START_SCALE) {
      b.material.opacity = Math.max(0, (sp.scale.y - 0.1) / (FADE_START_SCALE - 0.1));
      sp.position.z -= SMOKE_Z_DRIFT;
      b.startX *= SMOKE_SPREAD;
      b.startY *= SMOKE_SPREAD;
    }

    if (sp.scale.y <= 0.1) {
      this._context?.scene.remove(sp);
      b.material.dispose();
      return true;
    }
    return false;
  }

  protected override applyVisibility(visible: boolean): void {
    this._balls.forEach(b => { b.sphere.visible = visible; });
  }

  override dispose(): void {
    if (this._disposed) return;
    const scene = this._context?.scene;

    this._balls.forEach(b => {
      scene?.remove(b.sphere);
      b.material.dispose();
    });
    this._balls.clear();

    for (const mat of this._baseMats) mat.dispose();
    this._baseMats = [];

    super.dispose();
  }

  private _resolve(): ResolvedOpts {
    const o = this._opts;
    return {
      attachTo: o.attachTo ?? DEFAULTS.attachTo,
      spawnOffset: o.spawnOffset ?? DEFAULTS.spawnOffset,
      colors: (o.colors && o.colors.length > 0) ? o.colors : DEFAULTS.colors,
      dotsPerInterval: o.dotsPerInterval ?? DEFAULTS.dotsPerInterval,
      physicsScale: o.physicsScale ?? DEFAULTS.physicsScale,
    };
  }

  private _rnd(min: number, max: number): number {
    return Math.floor(Math.random() * max) + min;
  }
}

varying vec2 vUv;

void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

precision highp float;

uniform float uTime;
uniform float uProgress;
uniform float uOpacity;
uniform float uNoiseStrength;
uniform float uRevealSoftness;
uniform vec2 uResolution;
uniform vec2 uSize;
uniform vec3 uDarkColor;
uniform vec3 uLightColor;
uniform sampler2D tPerlin;
uniform sampler2D tNoise;

varying vec2 vUv;

float saturateFloat(float value) {
  return clamp(value, 0.0, 1.0);
}

float veilFbm(sampler2D textureSampler, vec2 uv) {
  float amplitude = 0.5;
  float value = 0.0;
  vec2 currentUv = uv;
  for (int index = 0; index < 4; index += 1) {
    value += texture2D(textureSampler, currentUv).r * amplitude;
    currentUv *= 2.03;
    amplitude *= 0.5;
  }
  return value;
}

float veilRidgedNoise(sampler2D textureSampler, vec2 uv) {
  float baseValue = veilFbm(textureSampler, uv);
  return 1.0 - abs(baseValue * 2.0 - 1.0);
}

void main() {
  vec2 safeResolution = max(uResolution, vec2(1.0));
  vec2 screenUv = gl_FragCoord.xy / safeResolution;
  float time = uTime * 0.18;
  vec2 flowUv = vUv * uSize;
  vec2 driftUv = flowUv;
  driftUv.x += sin(time * 0.42 + vUv.y * 4.8) * 0.035;
  driftUv.y += cos(time * 0.34 + vUv.x * 5.4) * 0.022;
  flowUv = mix(flowUv, driftUv, 0.72);
  vec2 largeCloudUv = flowUv * 0.05 + vec2(0.004 * time, -0.01 * time);
  vec2 midCloudUv = flowUv * 0.14 + vec2(-0.009 * time, 0.016 * time);
  vec2 fineCloudUv = flowUv * 0.33 + vec2(0.018 * time, -0.014 * time);
  float largeCloudNoise = veilFbm(tNoise, largeCloudUv);
  float largeCloudDetail = veilFbm(tPerlin, largeCloudUv * 1.6);
  float layeredCloudBase = smoothstep(
    0.42,
    0.88,
    largeCloudNoise * 0.62 + largeCloudDetail * 0.38
  );
  float layeredCloudRidge = veilRidgedNoise(tPerlin, midCloudUv * 0.82);
  float layeredCloudShadow = veilRidgedNoise(tNoise, fineCloudUv * 0.74);
  float cloudGapMask = 1.0 - smoothstep(0.36, 0.74, largeCloudNoise);
  float cloudBodyMask = smoothstep(0.48, 0.86, largeCloudNoise + layeredCloudRidge * 0.32);
  float cloudShadowMask = smoothstep(0.54, 0.92, layeredCloudShadow * largeCloudDetail);
  float baseNoise = texture2D(
    tNoise,
    flowUv * 0.18 + vec2(0.01 * time, -0.028 * time)
  ).r;
  float detailNoise = texture2D(
    tPerlin,
    flowUv * 0.42 + vec2(-0.012 * time, 0.02 * time)
  ).r;
  float bodyNoise = texture2D(
    tNoise,
    flowUv * 0.08 + vec2(0.006 * time, -0.018 * time)
  ).g;
  float curlNoise = texture2D(
    tPerlin,
    flowUv * 1.38 + vec2(-0.026 * time, 0.018 * time)
  ).g;
  float grainNoise = texture2D(
    tNoise,
    flowUv * 2.1 + vec2(0.034 * time, -0.022 * time)
  ).b;
  float microNoise = texture2D(
    tPerlin,
    flowUv * 3.4 + vec2(-0.04 * time, 0.028 * time)
  ).r;
  float plumeNoise = texture2D(
    tNoise,
    flowUv * 0.62 + vec2(0.014 * time, -0.01 * time)
  ).b;
  float erosionNoise = texture2D(
    tPerlin,
    flowUv * 4.6 + vec2(0.052 * time, -0.034 * time)
  ).g;

  vec2 distortedUv = vUv;
  distortedUv.x += (detailNoise - 0.5) * 0.11 * uNoiseStrength;
  distortedUv.y += (bodyNoise - 0.5) * 0.24 * uNoiseStrength;
  distortedUv.x += (curlNoise - 0.5) * 0.072 * uNoiseStrength;
  distortedUv.y += (plumeNoise - 0.5) * 0.06 * uNoiseStrength;

  float blanket = smoothstep(
    0.22,
    0.88,
    1.0 - distortedUv.y + 0.1 * (baseNoise - 0.5) + 0.08 * (plumeNoise - 0.5)
  );
  float cloudMass = smoothstep(
    0.24,
    0.88,
    baseNoise * 0.24 +
      plumeNoise * 0.28 +
      detailNoise * 0.16 +
      bodyNoise * 0.14 +
      curlNoise * 0.08 +
      (1.0 - distortedUv.y) * 0.4
  );
  float cloudBody = smoothstep(
    0.18,
    0.82,
    baseNoise * 0.22 +
      plumeNoise * 0.14 +
      detailNoise * 0.16 +
      bodyNoise * 0.14 +
      curlNoise * 0.14 +
      grainNoise * 0.08 +
      microNoise * 0.12 +
      erosionNoise * 0.14 +
      (1.0 - distortedUv.y) * 0.24
  );
  float wispNoise = texture2D(
    tPerlin,
    flowUv * 0.86 + vec2(0.018 * time, -0.01 * time)
  ).r;
  float textureLayer = smoothstep(
    0.24,
    0.78,
    detailNoise * 0.28 +
      bodyNoise * 0.14 +
      wispNoise * 0.16 +
      curlNoise * 0.18 +
      grainNoise * 0.1 +
      microNoise * 0.14
  );
  float erosion = smoothstep(0.22, 0.82, erosionNoise);
  float density = max(blanket * 0.24, cloudMass * 0.82);
  density = max(density, cloudBody);
  density = max(
    density,
    layeredCloudBase * (0.42 + layeredCloudRidge * 0.26)
  );
  density *= mix(0.72, 1.24, textureLayer);
  density *= mix(1.08, 0.72, erosion * (1.0 - textureLayer * 0.48));
  density *= mix(0.88, 1.08, layeredCloudShadow);
  density *= mix(1.0, 0.36, cloudGapMask);
  density += smoothstep(0.6, 0.9, curlNoise) * 0.08;
  density += smoothstep(0.68, 0.94, microNoise) * 0.05;
  density += smoothstep(0.58, 0.86, plumeNoise) * 0.08;
  density += smoothstep(0.56, 0.84, erosionNoise) * 0.06;
  density += smoothstep(0.54, 0.9, layeredCloudRidge) * 0.12;
  density += cloudBodyMask * 0.18;
  density = smoothstep(0.24, 0.90, density);
  density = saturateFloat(density);

  vec2 centeredUv = screenUv - 0.5;
  centeredUv.x *= safeResolution.x / safeResolution.y;
  float centerDistance = length(centeredUv);
  float revealNoiseA = texture2D(
    tNoise,
    screenUv * vec2(0.62, 0.44) + vec2(0.0, -0.014 * time)
  ).r - 0.5;
  float revealNoiseB = texture2D(
    tPerlin,
    screenUv * vec2(1.1, 0.78) + vec2(0.008 * time, 0.005 * time)
  ).r - 0.5;
  float revealNoise = revealNoiseA * 0.55 + revealNoiseB * 0.45;
  float revealRadius = mix(-0.36, 1.78, saturateFloat(uProgress));
  float revealEdge = centerDistance - revealRadius - 0.06 * revealNoise;
  float reveal = 1.0 - smoothstep(
    -max(uRevealSoftness, 0.0001),
    max(uRevealSoftness, 0.0001),
    revealEdge
  );

  float coverage = smoothstep(0.12, 0.62, density);
  float coverFloor = saturateFloat(1.0 - uProgress * 8.0);
  float alpha = max(mix(0.94, 1.0, coverage) * (1.0 - reveal) * uOpacity, coverFloor);
  vec3 color = mix(uDarkColor, uLightColor, smoothstep(0.25, 1.0, density));
  color = mix(vec3(0.62, 0.68, 0.78), vec3(1.0), smoothstep(0.20, 0.90, density));
  color *= mix(vec3(0.985, 0.988, 0.992), vec3(1.02, 1.018, 1.012), textureLayer * 0.48);
  color *= mix(vec3(0.99, 0.992, 0.996), vec3(1.018, 1.014, 1.008), plumeNoise * 0.42);
  color *= mix(vec3(0.992, 0.994, 0.997), vec3(1.016), curlNoise * 0.24);
  color *= mix(vec3(0.994, 0.995, 0.998), vec3(1.01), microNoise * 0.16);
  color *= mix(vec3(0.988, 0.989, 0.992), vec3(0.972, 0.974, 0.978), erosion * 0.18);
  color *= mix(vec3(0.992, 0.993, 0.996), vec3(1.0), detailNoise * 0.22);
  color *= mix(vec3(0.992, 0.994, 0.997), vec3(1.024, 1.02, 1.014), layeredCloudBase * 0.54);
  color *= mix(vec3(1.0), vec3(0.982, 0.984, 0.988), layeredCloudShadow * 0.18);
  color *= mix(vec3(1.0), vec3(1.035, 1.028, 1.018), cloudBodyMask * 0.52);
  color *= mix(vec3(1.0), vec3(0.88, 0.89, 0.91), cloudShadowMask * 0.34);

  gl_FragColor = vec4(color, saturateFloat(alpha));
}

uniform float uChapter;
uniform float uRatio;
varying vec2 vUv;
varying float vSeed, vRatio;
varying vec3 vNormal;
varying vec3 vViewDirection;

void main() {
    vUv = uv;
    vec3 transformed = position;
    transformed.y += uChapter * 0.01;
    vec4 worldPosition = modelMatrix * vec4(transformed, 1.0);
    vec4 mvPosition = viewMatrix * worldPosition;
    vNormal = normalize(normalMatrix * normal);
    vViewDirection = normalize(cameraPosition - worldPosition.xyz);
    vSeed = 0.0;
    vRatio = max(0.0001, uRatio);
    gl_Position = projectionMatrix * mvPosition;
}

