16	const DEFAULT_BLOOM: Required<Omit<BloomOptions, "selective">> & {
17	  selective: boolean;
18	} = {
19	  strength: 0.12,
20	  radius: 0.35,
21	  threshold: 0.93,
22	  compositeStrength: 0.4,
23	  selective: true,
24	};
25	
26	const DEFAULT_VIGNETTE: Required<VignetteOptions> = {
27	  offset: 0.95,
28	  darkness: 1.45,
29	};
30	
31	export class PostProcessor {
32	  private _renderer: THREE.WebGLRenderer;
33	  private _scene: THREE.Scene;
34	  private _camera: THREE.Camera;
35	  private _opts: PostProcessorOptions;
36	
37	  private _composer: EffectComposer | null = null;
38	  private _bloomComposer: EffectComposer | null = null;
39	  private _finalComposer: EffectComposer | null = null;
40	  private _bloomPass: UnrealBloomPass | null = null;
41	  private _blendPass: ShaderPass | null = null;
42	  private _vignettePass: ShaderPass | null = null;
43	  private _selective = false;
44	
45	  private _darkMaterial: THREE.MeshBasicMaterial | null = null;
46	  private _darkMaterialDepthOff: THREE.MeshBasicMaterial | null = null;
47	  private _materialCache = new Map<
48	    THREE.Object3D,
49	    THREE.Material | THREE.Material[]
50	  >();
51	  private _bloomDescendants = new Set<THREE.Object3D>();
52	  private _cachedBloomSignature = "";
53	  private _cachedNonBloomMeshes: THREE.Mesh[] = [];
54	  private _cachedSceneMeshes: THREE.Mesh[] = [];
55	  private _didWarnSelectiveFallback = false;
56	  private _lastHasRoots: boolean | null = null;
57	
58	  constructor(
59	    renderer: THREE.WebGLRenderer,
60	    scene: THREE.Scene,
61	    camera: THREE.Camera,
62	    opts: PostProcessorOptions = {},
63	  ) {
64	    this._renderer = renderer;
65	    this._scene = scene;
66	    this._camera = camera;
67	    this._opts = opts;
68	    this._setup();
69	  }
70	
71	  get isSelective(): boolean {
72	    return this._selective;
73	  }
74	
75	  private _setup(): void {
76	    const bloomOpt = this._opts.bloom;
77	    const vignetteOpt = this._opts.vignette;
78	    const hasBloom = bloomOpt !== false;
79	    const hasVignette = vignetteOpt !== false && vignetteOpt != null;
80	    if (!hasBloom && !hasVignette) {
81	      return;
82	    }
83	    const vignetteCfg = this._normalizeVignetteOptions(vignetteOpt);
84	    if (!hasBloom) {
85	      this._setupCustomPassPipeline(vignetteCfg);
86	      return;
87	    }
88	    const bloomCfg = this._normalizeBloomOptions(bloomOpt);
89	
90	    this._selective = bloomCfg.selective ?? true;
91	    const resolution = new THREE.Vector2(
92	      this._renderer.domElement.width,
93	      this._renderer.domElement.height,
94	    );
95	
96	    if (this._selective) {
97	      this._setupSelectiveBloom(bloomCfg, resolution, vignetteCfg);
98	      return;
99	    }
100	    this._setupGlobalBloom(bloomCfg, resolution, vignetteCfg);
101	  }
102	
103	  private _setupSelectiveBloom(
104	    cfg: Required<Omit<BloomOptions, "selective">> & { selective: boolean },
105	    resolution: THREE.Vector2,
106	    vignetteCfg: Required<VignetteOptions> | null,
107	  ): void {
108	    this._darkMaterial = new THREE.MeshBasicMaterial({ color: 0x000000 });
109	    this._darkMaterialDepthOff = new THREE.MeshBasicMaterial({
110	      color: 0x000000,
111	      depthTest: false,
112	      depthWrite: false,
113	    });
114	
115	    this._bloomComposer = new EffectComposer(this._renderer);
116	    this._bloomComposer.renderToScreen = false;
117	    this._bloomComposer.addPass(new RenderPass(this._scene, this._camera));
118	    this._bloomPass = new UnrealBloomPass(
119	      resolution,
120	      cfg.strength,
121	      cfg.radius,
122	      cfg.threshold,
123	    );
124	    this._bloomComposer.addPass(this._bloomPass);
125	
126	    this._finalComposer = new EffectComposer(this._renderer);
127	    this._finalComposer.addPass(new RenderPass(this._scene, this._camera));
128	
129	    const blendPass = new ShaderPass(
130	      new THREE.ShaderMaterial({
131	        uniforms: {
132	          baseTexture: { value: null },
133	          bloomTexture: {
134	            value: this._bloomComposer.renderTarget2.texture,
135	          },
136	          bloomMix: { value: cfg.compositeStrength },
137	        },
138	        vertexShader: additiveBlendVertexShader,
139	        fragmentShader: additiveBlendFragmentShader,
140	        defines: {},
141	      }),
142	      "baseTexture",
143	    );
144	    blendPass.needsSwap = true;
145	    this._blendPass = blendPass;
146	    this._finalComposer.addPass(blendPass);
147	    if (vignetteCfg) {
148	      this._vignettePass = this._createVignettePass(vignetteCfg);
149	      this._finalComposer.addPass(this._vignettePass);
150	    }
151	  }
152	
153	  private _setupGlobalBloom(
154	    bloomCfg: Required<Omit<BloomOptions, "selective">> & {
155	      selective: boolean;
156	    },
157	    resolution: THREE.Vector2,
158	    vignetteCfg: Required<VignetteOptions> | null,
159	  ): void {
160	    this._composer = new EffectComposer(this._renderer);
161	    this._composer.addPass(new RenderPass(this._scene, this._camera));
162	    this._bloomPass = new UnrealBloomPass(
163	      resolution,
164	      bloomCfg.strength,
165	      bloomCfg.radius,
166	      bloomCfg.threshold,
167	    );
168	    this._composer.addPass(this._bloomPass);
169	    if (vignetteCfg) {
170	      this._vignettePass = this._createVignettePass(vignetteCfg);
171	      this._composer.addPass(this._vignettePass);
172	    }
173	  }
174	
175	  private _setupCustomPassPipeline(
176	    vignetteCfg: Required<VignetteOptions> | null,
177	  ): void {
178	    this._composer = new EffectComposer(this._renderer);
179	    this._composer.addPass(new RenderPass(this._scene, this._camera));
180	    if (vignetteCfg) {
181	      this._vignettePass = this._createVignettePass(vignetteCfg);
182	      this._composer.addPass(this._vignettePass);
183	    }
184	  }
185	
186	  render(bloomRoots: Set<THREE.Object3D>, deltaTime?: number): void {
187	    if (!this._bloomPass) {
188	      if (this._composer) {
189	        this._composer.render(deltaTime);
190	        return;
191	      }
192	      this._renderer.render(this._scene, this._camera);
193	      return;
194	    }
195	
196	    if (this._selective) {
197	      const hasRoots = this._hasRenderableBloomRoots(bloomRoots);
198	      this._renderSelective(bloomRoots, hasRoots, deltaTime);
199	      return;
200	    }
201	    this._composer?.render(deltaTime);
202	  }
203	
204	  private _renderSelective(
205	    bloomRoots: Set<THREE.Object3D>,
206	    hasRoots: boolean,
207	    deltaTime?: number,
208	  ): void {
209	    if (
210	      !this._selective ||
211	      !this._bloomComposer ||
212	      !this._finalComposer ||
213	      !this._darkMaterial
214	    ) {
215	      this._composer?.render(deltaTime);
216	      return;
217	    }
218	    if (hasRoots !== this._lastHasRoots) {
219	      this._lastHasRoots = hasRoots;
220	      console.log(`[BLOOM:render] hasRoots changed → ${String(hasRoots)}  bloomRoots.size=${bloomRoots.size}`);
221	    }
222	    if (!hasRoots) {
223	      this._renderer.render(this._scene, this._camera);
224	      return;
225	    }
226	
227	    try {
228	      try {
229	        this._prepareBloomScene(hasRoots, bloomRoots);
230	        this._bloomComposer.render(deltaTime);
231	      } finally {
232	        this._restoreMaterials();
233	      }
234	      this._finalComposer.render(deltaTime);
235	    } catch (error) {
236	      if (!this._didWarnSelectiveFallback) {
237	        this._didWarnSelectiveFallback = true;
238	      }
239	      this._renderer.render(this._scene, this._camera);
240	    }
241	  }
242	
243	  private _prepareBloomScene(
244	    hasRoots: boolean,
245	    bloomRoots: Set<THREE.Object3D>,
246	  ): void {
247	    if (hasRoots) {
248	      this._darkenNonBloom(bloomRoots);
249	      return;
250	    }
251	    this._darkenAllMeshes();
252	  }
253	
254	  private _darkenNonBloom(bloomRoots: Set<THREE.Object3D>): void {
255	    this._materialCache.clear();
256	    const signature = this._createBloomSignature(bloomRoots);
257	    if (signature !== this._cachedBloomSignature) {
258	      this._cachedBloomSignature = signature;
259	      this._rebuildNonBloomMeshCache(bloomRoots);
260	    }
261	
262	    for (const mesh of this._cachedNonBloomMeshes) {
263	      this._materialCache.set(mesh, mesh.material);
264	      mesh.material = this._resolveDarkMaterial(mesh);
265	    }
266	  }
267	
268	  private _resolveDarkMaterial(mesh: THREE.Mesh): THREE.MeshBasicMaterial {
269	    const mat = mesh.material;
270	    const isDepthOff = Array.isArray(mat)
271	      ? mat.every((m) => m.depthTest === false)
272	      : (mat as THREE.Material).depthTest === false;
273	    if (isDepthOff) {
274	      console.log("[BLOOM:darken] depthOff mesh → darkDepthOff", {
275	        name: mesh.name || `(uuid:${mesh.uuid.slice(0, 8)})`,
276	        renderOrder: mesh.renderOrder,
277	        visible: mesh.visible,
278	        darkMaterialReady: this._darkMaterialDepthOff !== null,
279	      });
280	    }
281	    return (isDepthOff ? this._darkMaterialDepthOff : this._darkMaterial)!;
282	  }
283	
284	  private _darkenAllMeshes(): void {
285	    const dark = this._darkMaterial!;
286	    this._materialCache.clear();
287	    if (this._cachedSceneMeshes.length === 0) {
288	      this._cachedSceneMeshes = this._collectSceneMeshes();
289	    }
290	    for (const mesh of this._cachedSceneMeshes) {
291	      this._materialCache.set(mesh, mesh.material);
292	      mesh.material = dark;
293	    }
294	  }
295	
296	  private _hasRenderableBloomRoots(bloomRoots: Set<THREE.Object3D>): boolean {
297	    if (bloomRoots.size === 0) return false;
298	    for (const root of bloomRoots) {
299	      if (root.parent) return true;
300	    }
301	    return false;
302	  }
303	
304	  private _normalizeBloomOptions(
305	    bloomOpt: PostProcessorOptions["bloom"],
306	  ): Required<Omit<BloomOptions, "selective">> & { selective: boolean } {
307	    if (typeof bloomOpt !== "object" || bloomOpt == null) {
308	      return { ...DEFAULT_BLOOM };
309	    }
310	    const strength = this._clampFinite(
311	      bloomOpt.strength,
312	      DEFAULT_BLOOM.strength,
313	      0,
314	      5,
315	    );
316	    const radius = this._clampFinite(
317	      bloomOpt.radius,
318	      DEFAULT_BLOOM.radius,
319	      0,
320	      2,
321	    );
322	    const threshold = this._clampFinite(
323	      bloomOpt.threshold,
324	      DEFAULT_BLOOM.threshold,
325	      0,
326	      2,
327	    );
328	    const compositeStrength = this._clampFinite(
329	      bloomOpt.compositeStrength,
330	      DEFAULT_BLOOM.compositeStrength,
331	      0,
332	      1,
333	    );
334	    const selective =
335	      typeof bloomOpt.selective === "boolean"
336	        ? bloomOpt.selective
337	        : DEFAULT_BLOOM.selective;
338	    return { strength, radius, threshold, compositeStrength, selective };
339	  }
340	
341	  private _normalizeVignetteOptions(
342	    vignetteOpt: PostProcessorOptions["vignette"],
343	  ): Required<VignetteOptions> | null {
344	    if (vignetteOpt === false || vignetteOpt == null) return null;
345	    if (vignetteOpt === true) return { ...DEFAULT_VIGNETTE };
346	    return {
347	      offset: this._clampFinite(
348	        vignetteOpt.offset,
349	        DEFAULT_VIGNETTE.offset,
350	        0,
351	        4,
352	      ),
353	      darkness: this._clampFinite(
354	        vignetteOpt.darkness,
355	        DEFAULT_VIGNETTE.darkness,
356	        0,
357	        4,
358	      ),
359	    };
360	  }
361	
362	  private _createVignettePass(
363	    vignetteCfg: Required<VignetteOptions>,
364	  ): ShaderPass {
365	    const pass = new ShaderPass(VignetteShader);
366	    pass.uniforms.offset.value = vignetteCfg.offset;
367	    pass.uniforms.darkness.value = vignetteCfg.darkness;
368	    return pass;
369	  }
370	
371	  private _clampFinite(
372	    value: number | undefined,
373	    fallback: number,
374	    min: number,
375	    max: number,
376	  ): number {
377	    if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
378	    return Math.max(min, Math.min(max, value));
379	  }
380	
381	  private _restoreMaterials(): void {
382	    for (const [mesh, material] of this._materialCache) {
383	      (mesh as THREE.Mesh).material = material;
384	    }
385	    this._materialCache.clear();
386	  }
387	
388	  private _createBloomSignature(bloomRoots: Set<THREE.Object3D>): string {
389	    return Array.from(bloomRoots)
390	      .filter((root) => !!root.parent)
391	      .map((root) => root.uuid)
392	      .sort()
393	      .join("|");
394	  }
395	
396	  private _rebuildNonBloomMeshCache(bloomRoots: Set<THREE.Object3D>): void {
397	    this._bloomDescendants.clear();
398	    for (const root of bloomRoots) {
399	      root.traverse((child) => this._bloomDescendants.add(child));
400	    }
401	    this._cachedSceneMeshes = this._collectSceneMeshes();
402	    this._cachedNonBloomMeshes = this._cachedSceneMeshes.filter(
403	      (mesh) => !this._bloomDescendants.has(mesh),
404	    );
405	    const depthOffMeshes = this._cachedNonBloomMeshes.filter((m) => {
406	      const mat = m.material;
407	      return Array.isArray(mat)
408	        ? mat.every((x) => x.depthTest === false)
409	        : (mat as THREE.Material).depthTest === false;
410	    });
411	    console.log("[BLOOM:cache] rebuilt", {
412	      sceneMeshes: this._cachedSceneMeshes.length,
413	      nonBloomMeshes: this._cachedNonBloomMeshes.length,
414	      depthOffCount: depthOffMeshes.length,
415	      depthOff: depthOffMeshes.map((m) => ({
416	        name: m.name || `(uuid:${m.uuid.slice(0, 8)})`,
417	        renderOrder: m.renderOrder,
418	        materialType: Array.isArray(m.material) ? "multi" : m.material.type,
419	      })),
420	    });
421	  }
422	
423	  private _collectSceneMeshes(): THREE.Mesh[] {
424	    const meshes: THREE.Mesh[] = [];
425	    this._scene.traverse((obj) => {
426	      const mesh = obj as THREE.Mesh;
427	      if (!mesh.isMesh) return;
428	      meshes.push(mesh);
429	    });
430	    return meshes;
431	  }
432	
433	  resize(width: number, height: number, pixelRatio?: number): void {
434	    const dpr =
435	      pixelRatio ??
436	      Math.min(
437	        ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
438	        2,
439	      );
440	
441	    if (this._selective) {
442	      this._bloomComposer?.setSize(width, height);
443	      this._bloomComposer?.setPixelRatio(dpr);
444	      this._finalComposer?.setSize(width, height);
445	      this._finalComposer?.setPixelRatio(dpr);
446	    } else {
447	      this._composer?.setSize(width, height);
448	      this._composer?.setPixelRatio(dpr);
449	    }
450	
451	    if (this._bloomPass) {
452	      this._bloomPass.resolution.set(width, height);
453	    }
454	  }
455	
456	  getComposer(): EffectComposer | null {
457	    return this._selective ? this._finalComposer : this._composer;
458	  }
459	
460	  getBloomPass(): UnrealBloomPass | null {
461	    return this._bloomPass;
462	  }
463	
464	  getBloomOptions(): Required<Omit<BloomOptions, "selective">> | null {
465	    if (!this._bloomPass) return null;
466	    return {
467	      strength: this._bloomPass.strength,
468	      radius: this._bloomPass.radius,
469	      threshold: this._bloomPass.threshold,
470	      compositeStrength: this._readBloomCompositeStrength(),
471	    };
472	  }
473	
474	  setBloomOptions(options: BloomOptions): void {
475	    if (!this._bloomPass) return;
476	    const normalized = this._normalizeBloomOptions(options);
477	    this._bloomPass.strength = normalized.strength;
478	    this._bloomPass.radius = normalized.radius;
479	    this._bloomPass.threshold = normalized.threshold;
480	    const blendUniform = this._blendPass?.uniforms?.bloomMix;
481	    if (blendUniform) {
482	      blendUniform.value = normalized.compositeStrength;
483	    }
484	  }
485	
486	  getVignetteOptions(): Required<VignetteOptions> | null {
487	    const uniforms = this._vignettePass?.uniforms;
488	    if (!uniforms) return null;
489	    return {
490	      offset: uniforms.offset.value,
491	      darkness: uniforms.darkness.value,
492	    };
493	  }
494	
495	  setVignetteOptions(options: VignetteOptions): void {
496	    const uniforms = this._vignettePass?.uniforms;
497	    if (!uniforms) return;
498	    const normalized = this._normalizeVignetteOptions(options);
499	    if (!normalized) return;
500	    uniforms.offset.value = normalized.offset;
501	    uniforms.darkness.value = normalized.darkness;
502	  }
503	
504	  dispose(): void {
505	    this._composer?.dispose();
506	    this._composer = null;
507	    this._bloomComposer?.dispose();
508	    this._bloomComposer = null;
509	    this._finalComposer?.dispose();
510	    this._finalComposer = null;
511	    this._bloomPass?.dispose();
512	    this._bloomPass = null;
513	    this._blendPass = null;
514	    this._vignettePass = null;
515	    this._darkMaterial?.dispose();
516	    this._darkMaterial = null;
517	    this._darkMaterialDepthOff?.dispose();
518	    this._darkMaterialDepthOff = null;
519	    this._materialCache.clear();
520	    this._bloomDescendants.clear();
521	    this._cachedBloomSignature = "";
522	    this._cachedNonBloomMeshes = [];
523	    this._cachedSceneMeshes = [];
524	    this._didWarnSelectiveFallback = false;
525	  }
526	
527	  private _readBloomCompositeStrength(): number {
528	    const uniform = this._blendPass?.uniforms?.bloomMix;
529	    if (!uniform || typeof uniform.value !== "number") {
530	      return DEFAULT_BLOOM.compositeStrength;
531	    }
532	    return uniform.value;
533	  }
534	}
