uniform float uTime, uRatio, uChapter, uTransition, uOpacity, uRocketInfluence, uRocketRadius;
uniform vec3 uDarkColor, uLightColor;
uniform vec2 uSize, uResolution;
uniform vec2 uRocketUv;
uniform sampler2D tPerlin, tNoise, tMouse;
varying float vSeed, vRatio;
varying vec2 vUv;
varying vec3 vNormal;
varying vec3 vViewDirection;

void main() {
    vec2 ratioedUv = vec2(5.0, vRatio) * (vUv + vSeed * 0.1);
    vec2 resizedUv = uSize * ratioedUv;
    vec2 sUv = gl_FragCoord.xy / max(uResolution, vec2(1.0));
    float mouse = clamp(texture2D(tMouse, sUv + 0.1 * (texture2D(tNoise, 0.4 * resizedUv).g - 0.5)).r, 0.0, 1.0);
    float time = uTime * 0.5 / max(uSize.x, 0.0001);
    float strength = 1.0;
    vec2 dUv = vUv;
    dUv *= 1.0 + 0.03 * mouse;
    dUv += 0.05 * mouse;
    dUv.y += 0.3 * strength * (texture2D(tNoise, resizedUv * 0.2 + vec2(-0.004, -0.02) * time).r - 0.5);
    dUv.y -= 0.5 * strength * (texture2D(tNoise, resizedUv * 0.08 + vec2(0.005, 0.01) * time).r - 0.5);
    dUv.y *= 1.0 + 0.1 * strength * (texture2D(tPerlin, resizedUv * 0.5 - 0.01 * time).r - 0.5);
    float smoothness = smoothstep(0.4, 0.7, texture2D(tNoise, resizedUv * 0.08 + vec2(-0.08, -0.04) * time).r);
    float clouds = smoothstep(0.9 - 0.1 * smoothness, 0.7, dUv.y);
    clouds *= smoothstep(0.0, 0.2, dUv.y - 0.2 * smoothstep(0.4, 1.0, dUv.x));
  float alpha = clouds * smoothstep(1.0, 0.9, vUv.y) * smoothstep(0.0, 0.1, vUv.y) * smoothstep(0.0, 0.1, vUv.x) * smoothstep(1.0, 0.9, vUv.x);
  alpha += smoothstep(0.2, 0.3, vUv.y) * smoothstep(0.7, 0.6, vUv.y) * smoothstep(0.2, 0.3, vUv.x) * smoothstep(0.9, 0.8, vUv.x);
  alpha = min(1.0, alpha);
  float borderFadeX =
    smoothstep(0.0, 0.22, vUv.x) *
    smoothstep(0.0, 0.22, 1.0 - vUv.x);
  float borderFadeY =
    smoothstep(0.0, 0.18, vUv.y) *
    smoothstep(0.0, 0.18, 1.0 - vUv.y);
  vec2 radialUv = (vUv - 0.5) * vec2(1.18, 0.86);
  float radialFade = 1.0 - smoothstep(0.56, 0.96, length(radialUv));
  alpha *= borderFadeX * borderFadeY;
  alpha *= max(radialFade, clouds * 0.72);

  vec2 rocketDelta = vUv - uRocketUv;
  float rocketDistance = length(rocketDelta);
  float rocketHole =
    (1.0 - smoothstep(uRocketRadius, uRocketRadius + 0.12, rocketDistance)) *
    clamp(uRocketInfluence, 0.0, 1.0);
  alpha *= 1.0 - rocketHole * 0.42;

  float cloudDarkness = smoothstep(0.4, 1.0, dUv.y) + smoothstep(0.4, 0.0, dUv.y);
  vec3 normalDirection = normalize(vNormal);
  vec3 viewDirection = normalize(vViewDirection);
    float rim = pow(1.0 - clamp(dot(normalDirection, viewDirection), 0.0, 1.0), 2.4);
    vec3 color = mix(uDarkColor, uLightColor, clamp(cloudDarkness, 0.0, 1.0));
    color += uLightColor * 0.04 * rim * alpha;
    color = mix(color, uDarkColor, rocketHole * 0.18);

    float whiteText = smoothstep(2.2, 2.3, uChapter);
    color *= mix(vec3(1.0), vec3(0.8, 0.85, 0.87), whiteText);
    vec2 guillotineUv = vec2(uRatio, 1.0) * 0.4 * sUv;
    float guillotine = smoothstep(2.3, 2.2, uChapter - 0.3 * sUv.y + 0.1 * (texture2D(tNoise, guillotineUv + 0.02 * texture2D(tNoise, 4.0 * guillotineUv).r).r - 0.5));
    alpha *= guillotine;
    alpha *= smoothstep(1.0, 0.3, uTransition);
    alpha *= min(1.0, smoothstep(0.88, 0.96, vNormal.b) + smoothstep(0.05, 0.0, uTransition));
    gl_FragColor = vec4(color, alpha * clamp(uOpacity, 0.0, 1.0));
}

