455	function disposeContactHead(): void {
456	  mainSceneDomState.isContactHeadVisible = false;
457	  mainSceneDomState.contactHeadTimers = clearTimers(
458	    mainSceneDomState.contactHeadTimers,
459	  );
460	  mainSceneDomState.isContactActionsVisible = false;
461	  mainSceneDomState.contactActionTimers = clearTimers(
462	    mainSceneDomState.contactActionTimers,
463	  );
464	  const section = document.querySelector<HTMLElement>(CONTACT_SECTION_SELECTOR);
465	  const head = document.querySelector<HTMLElement>(CONTACT_HEAD_SELECTOR);
466	  const actions = document.querySelector<HTMLElement>(CONTACT_ACTIONS_SELECTOR);
467	  if (!section || !head || !actions) return;
468	  section.dataset.active = "false";
469	  head.dataset.active = "false";
470	  actions.dataset.active = "false";
471	  const textItems = Array.from(
472	    head.querySelectorAll<HTMLElement>(".mask-target"),
473	  );
474	  textItems.forEach((item) => TextReveal.setVisibleOff(item));
475	  const actionItems = Array.from(
476	    document.querySelectorAll<HTMLElement>(CONTACT_ACTION_ITEM_SELECTOR),
477	  );
478	  actionItems.forEach((item) => {
479	    item.classList.add(INIT_DOM_CLASSES.blockBase);
480	    item.classList.remove(INIT_DOM_CLASSES.blockUp, "is-block-reveal-down");
481	    item.classList.add(INIT_DOM_CLASSES.boxHidden);
482	  });
483	}
