import type { ObjectId, ObjectOptionsByKey } from "../types/object.types.js";
import type { ObjectResolvedConfig } from "../types/runtime.types.js";

export class ObjectConfigRuntime {
  resolve(
    objectId: keyof ObjectOptionsByKey,
    pageOptions: PageConfig["objectOptions"] | undefined,
    initialState: PageConfig["initialState"] | undefined,
  ): ObjectResolvedConfig {
    const merged = this._mergeSettings(
      this._getObjectSetting(objectId),
      this._mergeSettings(
        this._resolvePageOption(objectId, pageOptions),
        this._resolveInitialStateOverride(initialState, objectId as ObjectId),
      ),
    );
    const resolved = this._applyPerformanceOverrides(objectId, merged);
    if (!resolved) return {};
    const { effects, ...options } = resolved;
    return {
      options: Object.keys(options).length > 0 ? options : undefined,
      effects: this._isPlainRecord(effects) ? effects : undefined,
    };
  }

  private _getObjectSetting(
    objectId: keyof ObjectOptionsByKey,
  ): Record<string, unknown> | undefined {
    return OBJECT_CONFIG[objectId] as Record<string, unknown> | undefined;
  }

  private _resolvePageOption(
    objectId: keyof ObjectOptionsByKey,
    pageOptions: PageConfig["objectOptions"] | undefined,
  ): Record<string, unknown> | undefined {
    return pageOptions?.[objectId] as Record<string, unknown> | undefined;
  }

  private _resolveInitialStateOverride(
    initialState: PageConfig["initialState"] | undefined,
    objectId: ObjectId,
  ): Record<string, unknown> | undefined {
    const state = initialState?.[objectId];
    if (!this._isPlainRecord(state)) return undefined;

    const override: Record<string, unknown> = {};
    if (this._isPlainRecord(state.position)) {
      override.position = { ...state.position };
    }
    if (this._isPlainRecord(state.rotation)) {
      override.rotation = { ...state.rotation };
    }
    if (this._isPlainRecord(state.scale)) {
      override.scale = { ...state.scale };
    }
    if (typeof state.visible === "boolean") {
      override.visible = state.visible;
    }

    return Object.keys(override).length > 0 ? override : undefined;
  }

  private _mergeSettings(
    base: Record<string, unknown> | undefined,
    override: Record<string, unknown> | undefined,
  ): Record<string, unknown> | undefined {
    if (!base) return override ? { ...override } : undefined;
    if (!override) return { ...base };

    const merged: Record<string, unknown> = { ...base };
    for (const [key, value] of Object.entries(override)) {
      const current = merged[key];
      merged[key] =
        this._isPlainRecord(current) && this._isPlainRecord(value)
          ? this._mergeSettings(current, value)
          : value;
    }
    return merged;
  }

  private _applyPerformanceOverrides(
    objectId: keyof ObjectOptionsByKey,
    resolved: Record<string, unknown> | undefined,
  ): Record<string, unknown> | undefined {
    if (!resolved) return undefined;
    const performance = ResponsiveRuntime.getDefault().getSnapshot().performance;
    const next = { ...resolved };

    if (objectId === "clouds") {
      next.cloudCount = performance.cloudCount;
    }
    if (objectId === "cloudScene") {
      next.cloudCount = Math.round(performance.cloudCount * 10);
    }

    return next;
  }

  private _isPlainRecord(value: unknown): value is Record<string, unknown> {
    if (value == null || typeof value !== "object" || Array.isArray(value)) {
      return false;
    }
    const proto = Object.getPrototypeOf(value);
    return proto === Object.prototype || proto === null;
  }
}

